module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wire wclk,
    input wire winc,
    output wire wfull,
    input wire wresetn,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rinc,
    output wire rempty,
    input wire rrstn,
    output wire [WIDTH-1:0] rdata
);
    localparam ADDR_GRAY_WIDTH = $clog2(DEPTH);
    localparam ADDR_WIDTH = $clog2(DEPTH);


    reg [ADDR_GRAY_WIDTH-1:0] wptr_bin;
    wire [ADDR_GRAY_WIDTH-1:0] wptr_gray;
    reg [ADDR_GRAY_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync_rd;
    wire [ADDR_GRAY_WIDTH-1:0] wptr_gray_next;


    reg [ADDR_GRAY_WIDTH-1:0] rptr_bin;
    wire [ADDR_GRAY_WIDTH-1:0] rptr_gray;
    reg [ADDR_GRAY_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync_wr;


    always @(posedge wclk or negedge wresetn) begin
        if (!wresetn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync_rd <= 0;
        end else begin
            wptr_gray_sync1 <= rptr_gray;
            wptr_gray_sync_rd <= wptr_gray_sync1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync_wr <= 0;
        end else begin
            rptr_gray_sync1 <= wptr_gray;
            rptr_gray_sync_wr <= rptr_gray_sync1;
        end
    end


    assign wptr_gray_next = (wptr_bin + 1) ^ ((wptr_bin + 1) >> 1);
    assign wptr_gray = wptr_bin ^ (wptr_bin >> 1);
    assign rptr_gray = rptr_bin ^ (rptr_bin >> 1);


    wire full_cond = (wptr_gray_next[ADDR_GRAY_WIDTH-1] != wptr_gray_sync_rd[ADDR_GRAY_WIDTH-1]) &&
                     (wptr_gray_next[ADDR_GRAY_WIDTH-2] != wptr_gray_sync_rd[ADDR_GRAY_WIDTH-2]) &&
                     (wptr_gray_next[ADDR_GRAY_WIDTH-3:0] == wptr_gray_sync_rd[ADDR_GRAY_WIDTH-3:0]);
    wire empty_cond = (rptr_gray == wptr_gray_sync_rd);

    assign wfull = full_cond;
    assign rempty = empty_cond;


    always @(posedge wclk or negedge wresetn) begin
        if (!wresetn) begin
            wptr_bin <= 0;
        end else if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc) begin
            RAM[waddr] <= wdata;
        end
    end

    always @(posedge rclk) begin
        if (renc) begin
            rdata <= RAM[raddr];
        end
    end

endmodule

