module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

integer i;

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            SP <= 3'd4;
        end else begin
            case (RW)
                1'b0: begin 
                    if (!FULL) begin
                        stack_mem[SP-1] <= dataIn;
                        SP <= SP - 1;
                    end
                end
                1'b1: begin 
                    if (!EMPTY) begin
                        dataOut <= stack_mem[SP-1];
                        stack_mem[SP-1] <= 4'b0;
                        SP <= SP + 1;
                    end
                end
            endcase
        end
    end
end

endmodule

