module pulse_detect(clk, rst_n, data_in, data_out);
    input clk, rst_n, data_in;
    output reg data_out;
    reg [1:0] state;

    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= S0;
            data_out <= 0;
        end else begin
            case (state)
                S0: begin
                    if (data_in == 0) begin
                        state <= S1;
                        data_out <= 0;
                    end else begin
                        state <= S0;
                        data_out <= 0;
                    end
                end
                S1: begin
                    if (data_in == 1) begin
                        state <= S2;
                        data_out <= 0;
                    end else begin
                        state <= S0;
                        data_out <= 0;
                    end
                end
                S2: begin
                    if (data_in == 0) begin
                        state <= S0;
                        data_out <= 1;
                    end else begin
                        state <= S0;
                        data_out <= 0;
                    end
                end
                default: begin
                    state <= S0;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

