module traffic_light (
    input wire rst_n,
    input wire clk,
    input wire pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam [1:0] idle = 2'd0,
                     s1_red = 2'd1,
                     s2_yellow = 2'd2,
                     s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 3) ? s3_green : s1_red;
                s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
                s3_green: state <= (cnt == 3) ? s2_yellow : s3_green;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (~red && p_red) begin
                cnt <= 8'd10;
            end else if (~green && p_green) begin
                cnt <= 8'd60;
            end else if (~yellow && p_yellow) begin
                cnt <= 8'd5;
            end else begin
                cnt <= cnt - 8'd1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= (state == s1_red);
            yellow <= (state == s2_yellow);
            green <= (state == s3_green);
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            clock <= 8'd10;
        else
            clock <= cnt;
    end

endmodule

