module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] stored_dividend, stored_divisor;
    reg stored_sign;
    reg [7:0] stored_abs_dividend, stored_abs_divisor;
    reg stored_sign_dividend, stored_sign_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [16:0] SR;

    reg [7:0] quotient_reg;
    reg [8:0] remainder_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            stored_dividend <= 0;
            stored_divisor <= 0;
            stored_sign <= 0;
            stored_abs_dividend <= 0;
            stored_abs_divisor <= 0;
            stored_sign_dividend <= 0;
            stored_sign_divisor <= 0;
            NEG_DIVISOR <= 0;
            SR <= 0;
            quotient_reg <= 0;
            remainder_reg <= 0;
            result <= 0;
        end else begin
            if (res_valid) begin
                if (opn_valid && !res_valid) begin

                    stored_dividend <= dividend;
                    stored_divisor <= divisor;
                    stored_sign <= sign;


                    if (sign) begin
                        stored_abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                        stored_abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                        stored_sign_dividend <= dividend[7];
                        stored_sign_divisor <= divisor[7];
                    end else begin
                        stored_abs_dividend <= dividend;
                        stored_abs_divisor <= divisor;
                        stored_sign_dividend <= 0;
                        stored_sign_divisor <= 0;
                    end


                    NEG_DIVISOR <= ~stored_abs_divisor + 1;


                    SR <= {stored_abs_dividend, 1'b0} << 1;


                    quotient_reg <= 0;
                    remainder_reg <= 0;


                    cnt <= 4'd1;
                    start_cnt <= 1;
                    res_valid <= 0;
                end
            end else begin
                if (start_cnt) begin
                    if (cnt < 8) begin

                        remainder_reg <= SR[16:8] - NEG_DIVISOR;


                        if (remainder_reg[8] == 0) begin

                            SR <= {remainder_reg[7:0], quotient_reg << 1 | 1'b1};
                        end else begin
                            SR <= {SR[16:8], quotient_reg << 1};
                        end

                        cnt <= cnt + 1;
                    end else begin

                        start_cnt <= 0;
                        cnt <= 0;


                        if (stored_sign) begin
                            if (stored_sign_dividend ^ stored_sign_divisor)
                                quotient_reg <= ~quotient_reg + 1;
                            if (stored_sign_dividend)
                                remainder_reg <= ~remainder_reg + 1;
                        end


                        result <= {remainder_reg[7:0], quotient_reg};
                        res_valid <= 1;
                    end
                end
            end
        end
    end
endmodule

