always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 10'd0;
        count <= 2'd0;
        data_out <= 10'd0;
        valid_out <= 1'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            if (count == 2'd3) begin
                data_out <= sum_temp;
                valid_out <= 1'b1;
                sum_reg <= 10'd0;
                count <= 2'd0;
            end else begin
                sum_reg <= sum_temp;
                count <= count + 2'd1;
            end
        end
    end
end

endmodule

