module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a, b,
    output [N-1:0] c
);
    reg [N-1:0] res_with_sign;
    reg a_sign, b_sign;
    reg [N-1:0] sum;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] res;
    reg res_sign;
    integer i;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;
        if (a_sign == b_sign) begin
            sum = a + b;
            if (sum[N-1] != a_sign) begin

                if (a_sign)
                    res_with_sign = { {(N){1'b1}} };

                else
                    res_with_sign = {1'b0, {(N-1){1'b1}} };

            end else begin
                res_with_sign = sum;
            end
        end else begin
            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
                res_sign = a_sign;
            end else if (b_abs > a_abs) begin
                res = b_abs - a_abs;
                res_sign = b_sign;
            end else begin
                res = 0;
                res_sign = 0;
            end
            res_with_sign = {res_sign, res[N-2:0]};
        end
    end

    assign c = res_with_sign;

endmodule

