module fixed_point_subtractor #(parameter Q=3, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c = 0
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    reg [N-1:0] a_mag, b_mag;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];

    always @* begin
        if (sign_a == sign_b) begin

            res = a - b;
            res[N-1] = sign_a;
        end else begin

            a_mag = sign_a ? (~a + 1) : a;
            b_mag = sign_b ? (~b + 1) : b;

            if (a_mag > b_mag) begin
                res = a_mag + b_mag;
                res[N-1] = 0;
            end else begin
                res = a_mag - b_mag;
                res[N-1] = 1;
            end
        end


        if (res == 0)
            res[N-1] = 0;

        c = res;
    end
endmodule

