module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'd0;
        {a_sign, a_exponent, a_mantissa} <= 32'd0;
        {b_sign, b_exponent, b_mantissa} <= 32'd0;
        product <= 50'd0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        z_sign <= 0;
        z_exponent <= 0;
        z_mantissa <= 0;
    end else begin
        case (counter)
            3'd0: begin

                a_sign <= a[31];
                a_exponent <= a[30:23];
                a_mantissa <= a[22:0];
                b_sign <= b[31];
                b_exponent <= b[30:23];
                b_mantissa <= b[22:0];
                counter <= 3'd1;
            end

            3'd1: begin

                if (a_exponent == 8'hFF && a_mantissa != 0) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                end else if (b_exponent == 8'hFF && b_mantissa != 0) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                end else if (a_exponent == 8'hFF && a_mantissa == 0) begin
                    if (b_exponent == 8'hFF && b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                    end else begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end
                end else if (b_exponent == 8'hFF && b_mantissa == 0) begin
                    if (a_exponent == 8'hFF && a_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                    end else begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end
                end else if (a_exponent == 0 && a_mantissa == 0) begin
                    if (b_exponent == 8'hFF && b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                    end else begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                    end
                end else if (b_exponent == 0 && b_mantissa == 0) begin
                    if (a_exponent == 8'hFF && a_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h7FFFFF};

                    end else begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                    end
                end else begin

                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    counter <= 3'd2;
                end
            end

            3'd2: begin

                if (product[49]) begin

                    product <= product >> 1;
                    z_exponent <= z_exponent + 1;
                end

                guard_bit <= product[48];
                round_bit <= product[47];
                sticky <= |product[46:25];
                z_mantissa <= product[46:24];
                counter <= 3'd3;
            end

            3'd3: begin

                if (round_bit && (sticky || guard_bit)) begin
                    z_mantissa <= z_mantissa + 1;

                    if (z_mantissa[22]) begin
                        z_mantissa <= 23'h0;
                        z_exponent <= z_exponent + 1;
                    end
                end
                counter <= 3'd4;
            end

            3'd4: begin

                if (z_exponent >= 8'hFF) begin
                    z <= {z_sign, 8'hFF, 23'h0};

                end else if (z_exponent <= 0) begin
                    z <= {z_sign, 8'h0, 23'h0};

                end else begin
                    z <= {z_sign, z_exponent, z_mantissa};
                end
                counter <= 3'd0;
            end

            default: counter <= 3'd0;
        endcase
    end
end

endmodule

