module sub_64bit(A, B, result, overflow);
    input signed [63:0] A, B;
    output reg [63:0] result;
    output reg overflow;

    always @* begin
        result = A - B;

        overflow = ((~A[63]) & B[63] & result[63]) |  
                   (A[63] & (~B[63]) & (~result[63]));

    end
endmodule

