module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);

    localparam IDLE = 3'd0;
    localparam S1 = 3'd1;
    localparam S2 = 3'd2;
    localparam S3 = 3'd3;
    localparam S4 = 3'd4;

    reg [2:0] current_state, next_state;


