            IDLE: next_state = data_in ? S1 : IDLE;
            S1: next_state = (data_in == 0) ? S2 : IDLE;
            S2: next_state = (data_in == 0) ? S3 : IDLE;
            S3: next_state = (data_in == 1) ? S4 : IDLE;
            S4: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    assign sequence_detected = (current_state == S4);

endmodule

