module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam DEPTH_BITS = $clog2(DEPTH);


    reg [DEPTH_BITS-1:0] waddr_bin;
    wire [DEPTH_BITS-1:0] wptr_gray;
    always @(posedge wclk) begin
        if (~wrstn)
            waddr_bin <= 0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
    end
    assign wptr_gray = waddr_bin ^ (waddr_bin >> 1);


    reg [DEPTH_BITS-1:0] raddr_bin;
    wire [DEPTH_BITS-1:0] rptr_gray;
    always @(posedge rclk) begin
        if (~rrstn)
            raddr_bin <= 0;
        else if (rinc && !rempty)
            raddr_bin <= raddr_bin + 1;
    end
    assign rptr_gray = raddr_bin ^ (raddr_bin >> 1);


    reg [DEPTH_BITS-1:0] rptr_gray_sync1, rptr_gray_sync2;
    always @(posedge wclk) begin
        if (~wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end
    wire [DEPTH_BITS-1:0] rptr_gray_sync = rptr_gray_sync2;


    reg [DEPTH_BITS-1:0] wptr_gray_sync1, wptr_gray_sync2;
    always @(posedge rclk) begin
        if (~rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end
    wire [DEPTH_BITS-1:0] wptr_gray_sync = wptr_gray_sync2;


    assign wfull = (wptr_gray == {~rptr_gray_sync[DEPTH_BITS-1:DEPTH_BITS-2], rptr_gray_sync[DEPTH_BITS-3:0]});
    assign rempty = (rptr_gray == wptr_gray_sync);


    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );
endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end
endmodule

