module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW, EN, Rst, Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);
    reg [2:0] SP;
    reg [3:0] stack_mem [0:3];

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 4;
            dataOut <= 4'b0;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else if (EN) begin
            if (RW) begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP-1];
                    stack_mem[SP-1] <= 4'b0;
                    SP <= SP + 1;
                end
            end else begin 
                if (!FULL) begin
                    stack_mem[SP-1] <= dataIn;
                    SP <= SP - 1;
                end
            end
        end
    end

    assign EMPTY = (SP == 4);
    assign FULL = (SP == 0);

endmodule

