module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam IDLE = 1'b0;
    localparam UP   = 1'b1;

    reg state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= UP;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                UP: begin
                    if (data_in) begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b1;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end
endmodule

