module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] saved_dividend, saved_divisor;
    reg [7:0] abs_dividend, abs_divisor;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient, remainder;
    reg [8:0] neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
            neg_divisor <= 0;
        end else begin
            if (opn_valid && !res_valid && !start_cnt) begin

                saved_dividend <= dividend;
                saved_divisor <= divisor;
                if (sign) begin
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    neg_divisor <= -{1'b0, divisor[7] ? -divisor : divisor};
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    neg_divisor <= -{1'b0, divisor};
                end

                SR <= {abs_dividend, 1'b0};
                cnt <= 1;
                start_cnt <= 1;
            end else if (start_cnt && !res_valid) begin
                if (cnt < 8) begin

                    wire [8:0] temp_sub = {1'b0, SR[16:9]} - neg_divisor;
                    wire carry_out = ~temp_sub[8];

                    wire [8:0] new_remainder = carry_out ? temp_sub[8:1] : SR[16:9];
                    wire quotient_bit = carry_out;


                    SR <= {new_remainder, SR[7:0], quotient_bit};
                    cnt <= cnt + 1;
                end else begin

                    quotient <= SR[7:0];
                    remainder <= SR[16:9];
                    start_cnt <= 0;
                    cnt <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        if (saved_dividend[7] != saved_divisor[7]) begin
                            quotient <= -SR[7:0];
                            remainder <= -SR[16:9];
                        end
                    end
                end
            end else if (res_valid) begin
                if (opn_valid && !start_cnt) begin
                    res_valid <= 0;
                end
            end
            result <= {remainder, quotient};
        end
    end
endmodule

