 i <= 16;
 i = i + 1) begin : cla_loop

            assign P_bit[i] = P_bit[i-1] ^ (A[i] ^ B[i]);
            assign G_bit[i] = G_bit[i-1] | (P_bit[i-1] & (A[i] & B[i]));

            assign C[i] = G_bit[i-1] | (P_bit[i-1] & C[i-1]);
            assign sum[i] = P_bit[i] ^ C[i];
