module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire same_sign;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        same_sign = (sign_a == sign_b);

        if (same_sign) begin

            res = a - b;

            if (res == 0)
                res[N-1] = 0;
        end else begin

            reg [N-1:0] a_abs = sign_a ? -a : a;
            reg [N-1:0] b_abs = sign_b ? -b : b;
            reg [N-1:0] sum_abs = a_abs + b_abs;

            if (a_abs > b_abs)
                res = sum_abs;
            else
                res = sum_abs;


            res[N-1] = (a_abs > b_abs) ? 0 : 1;

            if (sum_abs == 0)
                res[N-1] = 0;
        end

        c = res;
    end
endmodule

