module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;

    reg [49:0] product;

    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 10'b0;
            b_exponent <= 10'b0;
            z_exponent <= 10'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            product <= 50'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= {1'b1, a[22:0]};

                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin 

                    if ((a_exponent == 10'hff && a_mantissa != 0) || 
                        (b_exponent == 10'hff && b_mantissa != 0)) begin
                        z <= {a_sign ^ b_sign, 31'h7fc00000};

                        counter <= 3'b111;
                    end

                    else if (a_exponent == 10'hff || b_exponent == 10'hff) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 10'hff;
                        z <= (a_mantissa == 0 && b_exponent == 10'hff) || 
                             (b_mantissa == 0 && a_exponent == 10'hff) ? 
                             {z_sign, 31'h7fc00000} : {z_sign, 31'h7f800000};
                        counter <= 3'b111;
                    end

                    else if (a_mantissa == 0 || b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 32'b0};
                        counter <= 3'b111;
                    end
                    else begin

                        product <= {a_mantissa, 27'b0} * {b_mantissa, 27'b0};
                        z_exponent <= a_exponent + b_exponent - 10'd127;
                        z_sign <= a_sign ^ b_sign;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin 
                    if (product[49]) begin 
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    guard_bit <= product[0];
                    round_bit <= product[1];
                    sticky <= |product[49:2];
                    counter <= counter + 1;
                end
                3'b011: begin 
                    if (guard_bit && (round_bit || sticky)) begin
                        if (product[1] || guard_bit) begin
                            product[0] <= product[0] + 1;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b100: begin 
                    if (z_exponent > 10'hfe) begin 
                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent < 10'b1) begin 
                        z <= {z_sign, 31'b0};
                    end else begin 
                        z <= {z_sign, z_exponent[7:0], product[49:23]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end
endmodule

