module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

wire signed [63:0] A_signed = $signed(A);
wire signed [63:0] B_signed = $signed(B);
wire signed [63:0] result_signed = A_signed - B_signed;

always @* begin
    result = result_signed;
    overflow = (~A_signed[63] & B_signed[63] & result_signed[63]) | 
              (A_signed[63] & ~B_signed[63] & ~result_signed[63]);
end

endmodule

