module asyn_fifo #(parameter WIDTH=8, DEPTH=16) (
    input wire wclk, rclk,
    input wire wrstn, rrstn,
    input wire winc, rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull, rempty,
    output wire [WIDTH-1:0] rdata
);
localparam PTR_WIDTH = $clog2(DEPTH) + 1;


reg [PTR_WIDTH-1:0] waddr_bin = 0;
reg [PTR_WIDTH-1:0] raddr_bin = 0;


wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;
assign wptr_gray = (waddr_bin >> 1) ^ waddr_bin;
assign rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


reg [PTR_WIDTH-1:0] rptr_syn1 = 0, rptr_syn = 0;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn1 <= 0;
        rptr_syn <= 0;
    end else begin
        rptr_syn1 <= rptr_gray;
        rptr_syn <= rptr_syn1;
    end
end


reg [PTR_WIDTH-1:0] wptr_syn1 = 0, wptr_syn = 0;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn1 <= 0;
        wptr_syn <= 0;
    end else begin
        wptr_syn1 <= wptr_gray;
        wptr_syn <= wptr_syn1;
    end
end


assign rempty = (rptr_gray == wptr_syn);
assign wfull = (wptr_gray == (rptr_syn ^ ( (1 << (PTR_WIDTH-1)) )) );


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) waddr_bin <= 0;
    else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) raddr_bin <= 0;
    else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
end


dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
    .wclk(wclk), .wenc(winc && !wfull),
    .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
    .wdata(wdata),
    .rclk(rclk), .renc(rinc && !rempty),
    .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
    .rdata(rdata)
);
