        if (EN) begin
            if (Rst) begin
                SP <= 4;
                dataOut <= 0;
                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 0;
            end else begin
                if (RW == 0 && SP != 0) begin
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end else if (RW == 1 && SP != 4) begin
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 0;
                    SP <= SP + 1;
                end
            end
        end
    end
endmodule

