module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg [1:0] state;
    parameter IDLE = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 0;
                    state <= data_in ? S1 : IDLE;
                end
                S1: begin
                    data_out <= 0;
                    state <= data_in ? S1 : S2;
                end
                S2: begin
                    data_out <= 1;
                    state <= IDLE;
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

