module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend;
reg [7:0] saved_divisor;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg sign_dividend;
reg sign_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] remainder;
reg [7:0] quotient;
reg [7:0] NEG_DIVISOR;
reg [8:0] temp_remainder;
reg [7:0] temp_quotient;
reg quotient_bit;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 16'b0;
        saved_dividend <= 8'b0;
        saved_divisor <= 8'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 0;
        remainder <= 8'b0;
        quotient <= 8'b0;
        NEG_DIVISOR <= 8'b0;
        temp_remainder <= 9'b0;
        temp_quotient <= 8'b0;
        quotient_bit <= 0;
    end else begin
        if (res_valid) begin
            res_valid <= 0;
            result <= {remainder, quotient};
        end else if (opn_valid && !res_valid) begin
            saved_dividend <= dividend;
            saved_divisor <= divisor;
            if (sign) begin
                sign_dividend <= dividend[7];
                sign_divisor <= divisor[7];
                abs_dividend <= (dividend[7]) ? (~dividend + 1) : dividend;
                abs_divisor <= (divisor[7]) ? (~divisor + 1) : divisor;
            end else begin
                sign_dividend <= 0;
                sign_divisor <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            SR <= {abs_dividend, 8'b0} << 1;
            NEG_DIVISOR <= -abs_divisor;
            cnt <= 4'd1;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt == 4'd8) begin
                start_cnt <= 0;
                cnt <= 0;
                remainder <= (sign_dividend) ? (~SR[15:8] + 1) : SR[15:8];
                quotient <= (sign_dividend ^ sign_divisor) ? (~SR[7:0] + 1) : SR[7:0];
                res_valid <= 1;
            end else begin
                temp_remainder = {1'b0, SR[15:8]} + {1'b0, abs_divisor};
                if (temp_remainder[8] == 0) begin
                    SR[15:8] <= temp_remainder[7:0];
                    quotient_bit <= 1;
                end else begin
                    quotient_bit <= 0;
                end
                SR <= {SR[14:0], quotient_bit};
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

