module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign, same_sign;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] temp_res;
    reg result_sign;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        same_sign = (a_sign == b_sign);

        if (same_sign) begin
            res = a - b;

            if (res == 0)
                result_sign = 1'b0;
            else
                result_sign = a_sign;
        end else begin

            a_abs = a_sign ? (~a + 1) : a;
            b_abs = b_sign ? (~b + 1) : b;


            if (a_abs > b_abs) begin
                temp_res = a_abs - b_abs;
                result_sign = a_sign;
            end else begin
                temp_res = b_abs - a_abs;
                result_sign = b_sign;
            end

            res = {result_sign, temp_res[N-2:0]};
        end
        c = res;
    end

endmodule

