module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};


                    if (a_exponent == 9'h000 && |a[22:0]) begin
                        z <= 32'h7FC00000;
                        counter <= 3'b111;
                    end else if (b_exponent == 9'h000 && |b[22:0]) begin
                        z <= 32'h7FC00000;
                        counter <= 3'b111;
                    end else if (a_exponent == 9'h0ff) begin
                        if (b_exponent == 9'h0ff) begin
                            if (b[22:0] == 0) begin

                                z <= {a_sign ^ b_sign, 9'h0ff, 23'h0};
                            end else begin
                                z <= 32'h7FC00000;

                            end
                        end else begin
                            z <= {a_sign ^ b_sign, 9'h0ff, 23'h0};
                        end
                        counter <= 3'b111;
                    end else if (b_exponent == 9'h0ff) begin
                        z <= {a_sign ^ b_sign, 9'h0ff, 23'h0};
                        counter <= 3'b111;
                    end else if (a_exponent == 9'h000) begin
                        z <= {a_sign ^ b_sign, 9'h000, 23'h0};
                        counter <= 3'b111;
                    end else if (b_exponent == 9'h000) begin
                        z <= {a_sign ^ b_sign, 9'h000, 23'h0};
                        counter <= 3'b111;
                    end else begin
                        counter <= 3'b001;
                    end
                end
                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end
                3'b010: begin

                    z_exponent <= a_exponent + b_exponent - 9'd127;
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 9'd1;
                    end
                    z_mantissa <= product[46:24];
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 3'b011;
                end
                3'b011: begin

                    if (guard_bit && (round_bit | sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'hFFFFFF) begin
                            z_exponent <= z_exponent + 9'd1;
                            z_mantissa <= 24'h0;
                        end
                    end
                    counter <= 3'b100;
                end
                3'b100: begin

                    if (z_exponent >= 9'h1FF) begin
                        z <= {z_sign, 9'h0FF, 23'h0};

                    end else if (z_exponent <= 9'h001) begin
                        z <= {z_sign, 9'h000, 23'h0};

                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b111;
                end
                default: begin
                    counter <= 3'b0;
                end
            endcase
        end
    end
