module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 3'd4;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else begin
            if (RW == 0) begin  
                if (SP != 3'd0) begin
                    stack_mem[SP - 3'd1] <= dataIn;
                    SP <= SP - 3'd1;
                end
            end else begin  
                if (SP != 3'd4) begin
                    if (SP == 3'd0) begin
                        dataOut <= stack_mem[3'd0];
                        stack_mem[3'd0] <= 4'b0;
                    end else begin
                        dataOut <= stack_mem[SP - 3'd1];
                        stack_mem[SP - 3'd1] <= 4'b0;
                    end
                    SP <= SP + 3'd1;
                end
            end
        end
    end
end

always @(*) begin
    EMPTY = (SP == 3'd4);
    FULL = (SP == 3'd0);
end

endmodule

