module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_abs, divisor_abs;
    reg dividend_sign, divisor_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] remainder, quotient;
    reg [7:0] divisor_abs_negated;
    wire [8:0] sum;
    reg carry_out;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 16'd0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            remainder <= 0;
            quotient <= 0;
            divisor_abs_negated <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end

            if (opn_valid && !start_cnt && !res_valid) begin

                dividend_sign <= dividend[7] & sign;
                divisor_sign <= divisor[7] & sign;
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

                SR <= {dividend_abs, 8'b0} << 1;

                divisor_abs_negated <= -divisor_abs;

                cnt <= 4'd1;
                start_cnt <= 1;
            end

            if (start_cnt) begin
                if (cnt == 4'd8) begin

                    if (sign) begin
                        result <= {dividend_sign ? -remainder : remainder, (dividend_sign ^ divisor_sign) ? -quotient : quotient};
                    end else begin
                        result <= {remainder, quotient};
                    end
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    sum = {1'b0, remainder} + {1'b0, divisor_abs_negated};
                    carry_out = sum[8];
                    if (carry_out) begin
                        remainder <= sum[7:0];
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end

                    SR <= {SR[14:0], carry_out};
                    cnt <= cnt + 1;
                end
