    a_reg = A;
    b_reg = B;
end


always @(a_reg, b_reg) begin
    reg [15:0] remainder = 16'b0;
    reg [15:0] quotient = 16'b0;
    integer i;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = remainder << 1;
        remainder[0] = a_reg[i];
        if (remainder >= {8'b0, b_reg}) begin
            quotient[i] = 1'b1;
            remainder = remainder - {8'b0, b_reg};
        end
    end
    result = quotient;
    odd = remainder;
end

