module fixed_point_adder #(parameter Q=2, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-2:0] a_mag, b_mag;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        a_mag = a[N-2:0];
        b_mag = b[N-2:0];

        if (a_sign == b_sign) begin

            res = {a_sign, a_mag + b_mag};
        end else begin

            if (a_mag > b_mag) begin
                res = {1'b0, a_mag - b_mag};
            end else if (b_mag > a_mag) begin
                res = {1'b1, b_mag - a_mag};
            end else begin

                res = {1'b0, {N-2{1'b0}}};
            end
        end
    end

    assign c = res;
endmodule

