    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [49:0] product;

    reg guard_bit, round_bit, sticky;
    reg [8:0] a_adj_exp, b_adj_exp, product_adj_exp;
    reg a_is_nan, b_is_nan, a_is_inf, b_is_inf, a_is_zero, b_is_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 9'd0;
            b_exponent <= 9'd0;
            z_exponent <= 9'd0;
            a_mantissa <= 24'd0;
            b_mantissa <= 24'd0;
            z_mantissa <= 24'd0;
            product <= 50'd0;
            a_is_nan <= 1'b0;
            b_is_nan <= 1'b0;
            a_is_inf <= 1'b0;
            b_is_inf <= 1'b0;
            a_is_zero <= 1'b0;
            b_is_zero <= 1'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_is_nan <= (|a[22:0]) && (a_exponent == 9'hff);
                    b_is_nan <= (|b[22:0]) && (b_exponent == 9'hff);

                    a_is_inf <= (a_exponent == 9'hff) && (a[22:0] == 23'd0);
                    b_is_inf <= (b_exponent == 9'hff) && (b[22:0] == 23'd0);

                    a_is_zero <= (a_exponent == 9'd0) && (a[22:0] == 23'd0);
                    b_is_zero <= (b_exponent == 9'd0) && (b[22:0] == 23'd0);
                    counter <= 3'd1;
                end
                3'd1: begin

                    if (a_is_nan || b_is_nan) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'hff;
                        z_mantissa <= 24'h000001;
                        counter <= 3'd8;
                    end else if (a_is_inf || b_is_inf) begin
                        if (a_is_zero || b_is_zero) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 24'd0;
                            counter <= 3'd8;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 24'd0;
                            counter <= 3'd8;
                        end
                    end else if (a_is_zero || b_is_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'd0;
                        z_mantissa <= 24'd0;
                        counter <= 3'd8;
                    end else begin


                        if (a_exponent == 9'd0) begin
                            a_mantissa <= {1'b0, a[22:0]};
                            a_adj_exp <= -126;
                        end else begin
                            a_mantissa <= {1'b1, a[22:0]};
                            a_adj_exp <= (a_exponent - 127);
                        end
                        if (b_exponent == 9'd0) begin
                            b_mantissa <= {1'b0, b[22:0]};
                            b_adj_exp <= -126;
                        end else begin
                            b_mantissa <= {1'b1, b[22:0]};
                            b_adj_exp <= (b_exponent - 127);
                        end
                        counter <= 3'd2;
                    end
                end
                3'd2: begin

                    product <= {26'd0, a_mantissa} * {26'd0, b_mantissa};
                    counter <= 3'd3;
                end
                3'd3: begin

                    product_adj_exp <= a_adj_exp + b_adj_exp + 127;
                    counter <= 3'd4;
                end
                3'd4: begin

                    if (product[49]) begin 
                        z_mantissa <= product[48:25];

                        z_exponent <= product_adj_exp + 1;
                    end else if (product[48]) begin
                        z_mantissa <= product[47:24];
                        z_exponent <= product_adj_exp;
                    end else begin
                        z_mantissa <= product[46:23];
                        z_exponent <= product_adj_exp;
                    end
                    counter <= 3'd5;
                end
                3'd5: begin

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'hffffff) begin
                            z_exponent <= z_exponent + 1;
                        end
                    end
                    counter <= 3'd6;
                end
                3'd6: begin

                    if (z_exponent >= 255) begin
                        z_exponent <= 255;
                        z_mantissa <= 0;
                    end else if (z_exponent <= 0) begin
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end
                    counter <= 3'd7;
                end
                3'd7: begin

                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    counter <= 3'd0;
                end
            endcase
        end
    end
endmodule

