module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam PTR_WIDTH = $clog2(DEPTH);
    localparam ADDR_WIDTH = $clog2(DEPTH);


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );


    reg [PTR_WIDTH-1:0] wptr_bin = 0;
    wire [PTR_WIDTH-1:0] wptr_gray = wptr_bin ^ (wptr_bin >> 1);
    reg [PTR_WIDTH-1:0] wptr_gray_wclk_sync1 = 0, wptr_gray_wclk_sync2 = 0;


    reg [PTR_WIDTH-1:0] rptr_bin = 0;
    wire [PTR_WIDTH-1:0] rptr_gray = rptr_bin ^ (rptr_bin >> 1);
    reg [PTR_WIDTH-1:0] rptr_gray_rclk_sync1 = 0, rptr_gray_rclk_sync2 = 0;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_rclk_sync1 <= 0;
            rptr_gray_rclk_sync2 <= 0;
        end else begin
            rptr_gray_rclk_sync1 <= rptr_gray;
            rptr_gray_rclk_sync2 <= rptr_gray_rclk_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_wclk_sync1 <= 0;
            wptr_gray_wclk_sync2 <= 0;
        end else begin
            wptr_gray_wclk_sync1 <= wptr_gray;
            wptr_gray_wclk_sync2 <= wptr_gray_wclk_sync1;
        end
    end


    assign wfull = (wptr_gray[PTR_WIDTH-1] != wptr_gray_wclk_sync2[PTR_WIDTH-1]) &&
                   (wptr_gray[PTR_WIDTH-2] != wptr_gray_wclk_sync2[PTR_WIDTH-2]) &&
                   (wptr_gray[PTR_WIDTH-3:0] == wptr_gray_wclk_sync2[PTR_WIDTH-3:0]);
    assign rempty = (rptr_gray == rptr_gray_rclk_sync2);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
        end else if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end

endmodule


