module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg state;
    localparam State_0 = 1'b0;
    localparam State_1 = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= State_0;
            data_out <= 1'b0;
        end else begin
            case (state)
                State_0: begin
                    state <= data_in ? State_1 : State_0;
                    data_out <= 1'b0;
