module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg, divisor_reg;
reg sign_quotient, sign_remainder;
reg [15:0] SR;
reg [7:0] NEG_DIVISOR;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        result <= 0;
        SR <= 0;
        NEG_DIVISOR <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        sign_quotient <= 0;
        sign_remainder <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_reg <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            divisor_reg <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            sign_quotient <= sign ? (dividend[7] ^ divisor[7]) : 0;
            sign_remainder <= sign ? dividend[7] : 0;

            SR <= {8'b0, (sign ? (dividend[7] ? -dividend : dividend) : dividend) << 1};

            NEG_DIVISOR <= sign ? ( (divisor[7] ? -divisor : divisor) * (-1) ) : (divisor * (-1));
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin
                reg [7:0] temp_remainder;
                reg new_remainder;
                reg new_quotient_bit;
                temp_remainder = SR[15:8] - NEG_DIVISOR;
                if (temp_remainder[7] == 0) begin 
                    new_remainder = temp_remainder;
                    new_quotient_bit = 1;
                end else begin
                    new_remainder = SR[15:8];
                    new_quotient_bit = 0;
                end

                SR <= {new_remainder, {new_quotient_bit, SR[7:1]}};
                cnt <= cnt + 1;
            end else begin

                reg [7:0] final_remainder = sign_remainder ? -SR[15:8] : SR[15:8];
                reg [7:0] final_quotient = sign_quotient ? -SR[7:0] : SR[7:0];
                result <= {final_remainder, final_quotient};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end
        end
    end
end

endmodule

