module fixed_point_adder #(parameter Q = 4, parameter N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] sum_abs;
    reg sign;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];

        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;


        if (a_sign == b_sign) begin
            sum_abs = a_abs + b_abs;
            sign = a_sign;
        end

        else begin
            if (a_abs > b_abs) begin
                sum_abs = a_abs - b_abs;
                sign = a_sign;
            end else if (b_abs > a_abs) begin
                sum_abs = b_abs - a_abs;
                sign = b_sign;
            end else begin 
                sum_abs = 0;
                sign = 0;
            end
        end


        res = {sign, sum_abs[N-2:0]};
        c = res;
    end
endmodule

