    input wire wrstn, rrstn,
    input wire winc, rinc,
    input wire [WIDTH-1:0] wdata,
    output wire [WIDTH-1:0] rdata,
    output wire wfull, rempty
);
    parameter DEPTH = 16;
    parameter WIDTH = 8;
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;

    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [ADDR_WIDTH-1:0] waddr, raddr;
    reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;
    reg [PTR_WIDTH-1:0] wptr_gray_sync_rclk1, wptr_gray_sync_rclk2;
    reg [PTR_WIDTH-1:0] rptr_gray_sync_wclk1, rptr_gray_sync_wclk2;


    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr),
        .rdata(rdata)
    );


    always @(posedge wclk) begin
        if (~wrstn) waddr_bin <= 0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end
    always @(posedge wclk) begin
        if (~wrstn) wptr_gray <= 0;
        else wptr_gray <= waddr_bin ^ (waddr_bin >> 1);
    end


    always @(posedge rclk) begin
        if (~rrstn) raddr_bin <= 0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end
    always @(posedge rclk) begin
        if (~rrstn) rptr_gray <= 0;
        else rptr_gray <= raddr_bin ^ (raddr_bin >> 1);
    end


    always @(posedge rclk) begin
        if (~rrstn) {wptr_gray_sync_rclk1, wptr_gray_sync_rclk2} <= 0;
        else {wptr_gray_sync_rclk1, wptr_gray_sync_rclk2} <= {wptr_gray, wptr_gray_sync_rclk1};
    end
    always @(posedge wclk) begin
        if (~wrstn) {rptr_gray_sync_wclk1, rptr_gray_sync_wclk2} <= 0;
        else {rptr_gray_sync_wclk1, rptr_gray_sync_wclk2} <= {rptr_gray, rptr_gray_sync_wclk1};
    end


    wire [PTR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync_wclk2;
    wire [PTR_WIDTH-1:0] wptr_gray_inverted = {~rptr_gray_sync[PTR_WIDTH-1], ~rptr_gray_sync[PTR_WIDTH-2], rptr_gray_sync[PTR_WIDTH-3:0]};
    assign wfull = (wptr_gray == wptr_gray_inverted);
    assign rempty = (rptr_gray == wptr_gray_sync_rclk2);

    assign waddr = waddr_bin[ADDR_WIDTH-1:0];
    assign raddr = raddr_bin[ADDR_WIDTH-1:0];
endmodule

