integer i;


assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            SP <= 3'd4;

        end else begin
            if (!FULL && !RW) begin 
                stack_mem[SP] <= dataIn;
                SP <= SP - 3'd1;
            end else if (!EMPTY && RW) begin 
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 3'd1;
            end
        end
    end
end

endmodule

