module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red, yellow, green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_green_prev, p_yellow_prev, p_red_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 8'd0)
                        state <= s3_green;
                end
                s2_yellow: begin
                    if (cnt == 8'd0)
                        state <= s1_red;
                end
                s3_green: begin
                    if (cnt == 8'd0)
                        state <= s2_yellow;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_green_prev <= 0;
            p_yellow_prev <= 0;
            p_red_prev <= 0;
        end else begin
            p_green_prev <= p_green;
            p_yellow_prev <= p_yellow;
            p_red_prev <= p_red;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;

        end else begin
            if (pass_request && p_green) begin

                cnt <= 8'd10;
            end else if (!p_green && p_green_prev) begin

                cnt <= 8'd59;

            end else if (!p_yellow && p_yellow_prev) begin

                cnt <= 8'd4;

            end else if (!p_red && p_red_prev) begin

                cnt <= 8'd9;

            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;

            case (state)
                idle: {red, yellow, green} <= 3'b000;
                s1_red: red <= 1;
                s2_yellow: yellow <= 1;
                s3_green: green <= 1;
            endcase
        end
    end

    assign clock = cnt;

endmodule

