    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg buffer_ready;
reg [15:0] output_data;
reg output_next_cycle;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock <= 8'b0;
        buffer_ready <= 1'b0;
        data_out <= 16'b0;
        valid_out <= 1'b0;
        output_data <= 16'b0;
        output_next_cycle <= 1'b0;
    end else begin

        valid_out <= output_next_cycle;
        data_out <= output_data;


        output_next_cycle <= 1'b0;


        if (buffer_ready) begin
            if (valid_in) begin

                output_data <= {data_lock, data_in};
                output_next_cycle <= 1'b1;
                buffer_ready <= 1'b0;
            end
        end else begin
            if (valid_in) begin

                data_lock <= data_in;
                buffer_ready <= 1'b1;
            end
        end
    end
end

