reg sign_quotient, sign_remainder;
reg [8:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] divisor_abs;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        result <= 0;
        saved_dividend <= 0;
        saved_divisor <= 0;
        sign_quotient <= 0;
        sign_remainder <= 0;
        SR <= 0;
        divisor_abs <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            saved_dividend <= sign ? ((dividend[7]) ? (~dividend + 1) : dividend) : dividend;
            saved_divisor <= sign ? ((divisor[7]) ? (~divisor + 1) : divisor) : divisor;
            divisor_abs <= sign ? ((divisor[7]) ? (~divisor + 1) : divisor) : divisor;

            sign_quotient <= sign ? (dividend[7] ^ divisor[7]) : 0;
            sign_remainder <= sign ? dividend[7] : 0;

