                if (temp_sub[9]) begin
                    SR[8:0] <= temp_sub[8:0];
                    SR[7:0] <= {SR[7:0][6:0], 1'b1};
                end else begin
                    SR[7:0] <= {SR[7:0][6:0], 1'b0};
                end
                cnt <= cnt + 4'd1;
            end else begin

                start_cnt <= 0;

                result[15:8] <= sign_remainder ? (~SR[8:1] + 1) : SR[8:1];
                result[7:0] <= sign_quotient ? (~SR[7:0] + 1) : SR[7:0];
                res_valid <= 1;
            end
        end else begin

        end
    end
end

