module fixed_point_subtractor #(parameter Q=2, N=8) (
    input wire [N-1:0] a, b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign, b_sign;
    wire same_sign;
    wire [N-1:0] temp_b, sum;

    assign a_sign = a[N-1];
    assign b_sign = b[N-1];
    assign same_sign = (a_sign == b_sign);

    always @(*) begin
        if (same_sign) begin
            res = a - b;
            res[N-1] = a_sign;
        end else begin
            if (a_sign == 0 && b_sign == 1) begin
                temp_b = ~b + 1;
                sum = a + temp_b;
                res[N-1] = (a > temp_b) ? 1'b0 : 1'b1;
            end else begin
                temp_b = ~a + 1;
                sum = temp_b + b;
                res[N-1] = (temp_b > b) ? 1'b0 : 1'b1;
            end
            res = sum;
        end


        if (res == 0) begin
            res[N-1] = 0;
        end

        c = res;
    end
endmodule

