module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg sign_reg;
    reg [8:0] dividend_abs, divisor_abs;
    reg sign_quotient, sign_remainder;
    reg [16:0] SR;

    reg [8:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg start_cnt;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            NEG_DIVISOR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_reg <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sign_reg <= sign;

                if (sign) begin

                    dividend_abs <= (dividend[7]) ? -{1'b0, dividend} : {1'b0, dividend};
                    divisor_abs <= (divisor[7]) ? -{1'b0, divisor} : {1'b0, divisor};
                    sign_quotient <= (dividend[7] ^ divisor[7]);
                    sign_remainder <= dividend[7];
                end else begin
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                end


                SR <= {dividend_abs, 1'b0} << 1;
                NEG_DIVISOR <= -divisor_abs;
                cnt <= 4'd1;
                start_cnt <= 1;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    reg [8:0] temp_remainder = SR[16:8] - NEG_DIVISOR;
                    reg quotient_bit;

                    if (temp_remainder[8] == 0) begin
                        SR[16:8] <= temp_remainder[7:0];
                        quotient_bit = 1;
                    end else begin
                        quotient_bit = 0;
                    end

                    SR <= {SR[15:0], quotient_bit};
                    cnt <= cnt + 1;
                end else begin

                    reg [7:0] quotient = SR[7:0];
                    reg [7:0] remainder = SR[16:9];

                    if (sign_reg) begin
                        if (sign_quotient) quotient <= -quotient;
                        if (sign_remainder) remainder <= -remainder;
                    end

                    result <= {remainder, quotient};
                    start_cnt <= 0;
                    res_valid <= 1;
                end
            end
        end
    end


    always @(posedge clk) begin
        if (opn_valid && !res_valid) begin
            res_valid <= 0;
        end
    end
endmodule

