module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;

    reg [15:0] a_reg, b_reg;
    integer i;
    reg [8:0] remainder;



    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        result = 0;
        remainder = 0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            remainder = {remainder[7:0], a_reg[i]};

            if (remainder >= b_reg) begin
                result[i] = 1'b1;
                remainder = remainder - b_reg;
            end
        end

        odd = {8'b0, remainder[7:0]};
    end
endmodule

