                if (i == 5'd0) begin
                    areg <= ain;
                    breg <= bin;
                end else if ((i > 5'd0) && (i < 5'd17)) begin
                    if (areg[i-1]) begin
                        yout_r <= yout_r + (breg << (i-1));
                    end
                end
            end else begin
                areg <= 16'd0;
                breg <= 16'd0;
                yout_r <= 32'd0;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done_r <= 1'b0;
        end else begin
            if (i == 5'd16) begin
                done_r <= 1'b1;
            end else if (i == 5'd17) begin
                done_r <= 1'b0;
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

