module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg sign_a, sign_b;
reg [N-2:0] abs_a, abs_b;
reg [N-2:0] res_value;
reg sign;
reg [N-1:0] res;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];

    abs_a = sign_a ? (~a + 1) : a;
    abs_b = sign_b ? (~b + 1) : b;

    if (sign_a == sign_b) begin
        res_value = abs_a - abs_b;
        sign = sign_a;
    end else begin
        if (sign_a == 1'b0) begin
            if (abs_a > abs_b) begin
                res_value = abs_a - abs_b;
                sign = 1'b0;
            end else begin
                res_value = abs_b - abs_a;
                sign = 1'b1;
            end
        end else begin
            if (abs_a > abs_b) begin
                res_value = abs_a - abs_b;
                sign = 1'b1;
            end else begin
                res_value = abs_b - abs_a;
                sign = 1'b0;
            end
        end
    end

    if (res_value == 0)
        sign = 1'b0;

    res = {sign, res_value};
end

assign c = res;

endmodule

