    reg [22:0] a_mantissa_frac, b_mantissa_frac;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            z_exponent <= 8'b0;
            a_mantissa_frac <= 23'b0;
            b_mantissa_frac <= 23'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            product <= 48'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
