            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa_frac <= a[22:0];
                    b_mantissa_frac <= b[22:0];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if ((a_exponent == 8'hff && a_mantissa_frac != 0) || (b_exponent == 8'hff && b_mantissa_frac != 0)) begin
                        z <= 32'h7fc00000;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin
                        if ((a_exponent == 8'hff && a_mantissa_frac == 0) && (b_exponent == 8'hff && b_mantissa_frac == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                        end else if ((a_exponent == 8'hff && a_mantissa_frac == 0) && (b_exponent == 8'h00 || (b_exponent == 8'hff && b_mantissa_frac != 0))) begin
                            z <= 32'h7fc00000;
                        end else if ((b_exponent == 8'hff && b_mantissa_frac == 0) && (a_exponent == 8'h00 || (a_exponent == 8'hff && a_mantissa_frac != 0))) begin
                            z <= 32'h7fc00000;
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                        end
                    end else if ((a_exponent == 8'h00 && a_mantissa_frac == 0) || (b_exponent == 8'h00 && b_mantissa_frac == 0)) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b010: begin
                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    counter <= counter + 1;
                end
                3'b011: begin

                    if (product[47]) begin
                        z_mantissa <= product[46:23];
                        z_exponent <= z_exponent + 8'd1;
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
                    end else begin
                        z_mantissa <= product[47:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    reg round;
                    reg [23:0] rounded_mantissa;
                    reg [7:0] rounded_exponent;
                    round = guard_bit & (round_bit | sticky);
                    if (round) rounded_mantissa = z_mantissa + 24'd1;
                    else rounded_mantissa = z_mantissa;
                    if (rounded_mantissa[23]) begin
                        rounded_mantissa = 24'd1;
                        rounded_exponent = z_exponent + 8'd1;
                    end else begin
                        rounded_exponent = z_exponent;
                    end
                    z_mantissa = rounded_mantissa;
                    z_exponent = rounded_exponent;
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (z_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 31'd0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end
