    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg wfull,
    input rclk,
    input rrstn,
    input rinc,
    output reg rempty,
    output reg [WIDTH-1:0] rdata
);
localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH;

reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
