function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

wire full, empty;
wire [PTR_WIDTH-1:0] wptr_gray_next = bin2gray(waddr_bin_next);

dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
    .wclk(wclk),
    .wenc(wfull ? 1'b0 : winc),
    .waddr(waddr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rempty ? 1'b0 : rinc),
    .raddr(raddr_bin),
    .rdata(rdata)
);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr_gray <= 0;
    end else begin
        waddr_bin <= waddr_bin_next;
        wptr_gray <= bin2gray(waddr_bin_next);
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr_gray <= 0;
    end else begin
        raddr_bin <= raddr_bin_next;
        rptr_gray <= bin2gray(raddr_bin_next);
    end
end

always @(posedge wclk) begin
    wptr_sync1 <= rptr_gray;
    wptr_sync2 <= wptr_sync1;
end

always @(posedge rclk) begin
    rptr_sync1 <= wptr_gray;
    rptr_sync2 <= rptr_sync1;
end

assign waddr_bin_next = waddr_bin + (winc & ~wfull);
assign raddr_bin_next = raddr_bin + (rinc & ~rempty);

assign full = (wptr_gray_next[PTR_WIDTH-1] != rptr_sync2[PTR_WIDTH-1]) &&
              (wptr_gray_next[PTR_WIDTH-2] != rptr_sync2[PTR_WIDTH-2]) &&
              (wptr_gray_next[PTR_WIDTH-3:0] == rptr_sync2[PTR_WIDTH-3:0]);
assign empty = (rptr_gray == wptr_sync2);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull <= 0;
    else wfull <= full;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty <= 1'b1;
    else rempty <= empty;
end
endmodule

