module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 3'b100;
            EMPTY <= 1'b1;
            FULL <= 1'b0;
            dataOut <= 4'b0;

            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else begin
            reg [2:0] next_SP;
            next_SP = SP;

            if (!FULL && !RW) begin
                stack_mem[SP - 3'd1] <= dataIn;
                next_SP = SP - 3'd1;
            end

            else if (!EMPTY && RW) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                next_SP = SP + 3'd1;
            end

            SP <= next_SP;
            EMPTY <= (next_SP == 3'b100);
            FULL <= (next_SP == 3'b000);
        end
    end
end

