module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg sign_reg;
    reg [3:0] cnt;
    reg [15:0] SR;
    reg start_cnt;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [7:0] NEG_DIVISOR;


    wire [7:0] abs_dividend = sign_reg ? (~dividend_reg + 1) : dividend_reg;
    wire [7:0] abs_divisor = sign_reg ? (~divisor_reg + 1) : divisor_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_reg <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            result <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sign_reg <= sign;


                if (sign) begin

                    dividend_reg <= (dividend[7]) ? (~dividend + 1) : dividend;
                    divisor_reg <= (divisor[7]) ? (~divisor + 1) : divisor;
                end else begin
                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                end


                SR <= {abs_dividend, 1'b0};

                NEG_DIVISOR <= ~abs_divisor + 1;
                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin

                    start_cnt <= 0;
                    cnt <= 0;

                    if (sign) begin

                        reg quotient_sign, remainder_sign;
                        reg [7:0] quotient_abs, remainder_abs;
                        quotient_abs = quotient;
                        remainder_abs = remainder;

                        quotient_sign = dividend_reg[7] ^ divisor_reg[7];
                        remainder_sign = dividend_reg[7];

                        if (quotient_sign) quotient <= ~quotient + 1;
                        else quotient <= quotient;

                        if (remainder_sign) remainder <= ~remainder + 1;
                        else remainder <= remainder;
                    end else begin

                        quotient <= quotient;
                        remainder <= remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin

                    reg [8:0] sum;
                    sum = {1'b0, SR[15:8]} + {1'b0, abs_divisor};
                    if (sum[8] == 0) begin

                        SR[15:8] <= sum[7:0];
                        SR[7:0] <= {SR[6:0], 1'b1};
                    end else begin

                        SR[7:0] <= {SR[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end else begin
                res_valid <= res_valid & ~opn_valid;
            end
        end
    end
endmodule

