module div_16bit(A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result;
output reg [15:0] odd;

reg [15:0] a_reg, b_reg;


always @(A, B) begin
    a_reg <= A;
    b_reg <= B;
end


always @(a_reg, b_reg) begin
    reg [15:0] remainder;
    reg [15:0] quotient;
    integer i;

    remainder = 16'b0;
    quotient = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = (remainder << 1) | ((a_reg >> i) & 1);
        if (remainder >= b_reg) begin
            remainder = remainder - b_reg;
            quotient[i] = 1'b1;
        end
    end

    result = quotient;
    odd = {8'b0, remainder};

end

endmodule

