    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G,
    output P
);
    wire [16:1] g, p, c;


    genvar i;
    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : pg
            assign g[i] = A[i] & B[i];
            assign p[i] = A[i] ^ B[i];
