module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] larger, smaller;
    reg sign;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            reg [N-1:0] sum;
            sum = a + b;
            if (a_sign) begin

                if (sum[N-1] != a_sign) begin
                    res = {1'b1, {(N-1){1'b0}}};

                end else begin
                    res = sum;
                end
            end else begin

                if (sum[N-1] != a_sign) begin
                    res = {1'b0, {(N-1){1'b1}}};

                end else begin
                    res = sum;
                end
            end
            sign = a_sign;
        end else begin

            abs_a = a_sign ? (~a + 1) : a;
            abs_b = b_sign ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                larger = abs_a;
                smaller = abs_b;
                sign = a_sign;
            end else begin
                larger = abs_b;
                smaller = abs_a;
                sign = b_sign;
            end
            res = larger - smaller;
            res[N-1] = sign;
        end
        c = res;
    end
endmodule

