module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-2:0] magnitude_a, magnitude_b;
    reg [N-2:0] magnitude_result;
    reg result_sign;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        magnitude_a = a[N-2:0];
        magnitude_b = b[N-2:0];

        if (sign_a == sign_b) begin

            magnitude_result = magnitude_a - magnitude_b;
            result_sign = sign_a;
        end else begin

            magnitude_result = magnitude_a + magnitude_b;
            result_sign = (magnitude_a > magnitude_b) ? sign_a : sign_b;
        end


        if (magnitude_result == 0)
            result_sign = 0;

        res = {result_sign, magnitude_result};
        c = res;
    end
endmodule

