module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, sum_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [47:0] product_shifted;
    reg [7:0] adjusted_exponent;

    wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
    wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 0);
    wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
    wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            sum_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            product_shifted <= 0;
            adjusted_exponent <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if (a_is_nan || b_is_nan) begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end else if (a_is_inf || b_is_inf) begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (a_is_zero || b_is_zero) begin
                        if (a_is_inf || b_is_inf)
                            z <= {1'b0, 8'hff, 23'h1};
                        else
                            z <= 32'h0;
                    end else begin
                        sum_exponent <= a_exponent + b_exponent - 10'd127;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin

                    z_sign <= a_sign ^ b_sign;
                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end
                3'b011: begin

                    if (product[47]) begin
                        product_shifted <= product >> 1;
                        sum_exponent <= sum_exponent + 1;
                    end else begin
                        product_shifted <= product;
                        sum_exponent <= sum_exponent;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    guard_bit <= product_shifted[22];
                    round_bit <= product_shifted[21];
                    sticky <= |product_shifted[20:0];
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        product_shifted <= product_shifted + 1;
                    end

                    if (product_shifted[47] && (product_shifted[46:0] >= 48'h800000000000)) begin
                        product_shifted <= product_shifted >> 1;
                        sum_exponent <= sum_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                3'b110: begin

                    adjusted_exponent <= sum_exponent;
                    if (sum_exponent >= 255)
                        adjusted_exponent <= 8'hff;
                    else if (sum_exponent <= 0)
                        adjusted_exponent <= 8'h0;
                    counter <= counter + 1;
                end
                3'b111: begin

                    z <= {z_sign, adjusted_exponent, product_shifted[46:23]};
                    counter <= 3'b000;
                end
            endcase
        end
    end
endmodule

