module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    parameter IDLE = 1'b0;
    parameter STATE1 = 1'b1;
    reg state_reg, state_next;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state_reg <= IDLE;
            data_out <= 1'b0;
        end else begin
            state_reg <= state_next;
            case (state_reg)
                IDLE: begin
                    data_out <= 1'b0;
                    state_next <= data_in ? STATE1 : IDLE;
                end
                STATE1: begin
                    if (data_in) begin
                        data_out <= 1'b0;
                        state_next <= IDLE;
                    end else begin
                        data_out <= 1'b1;
                        state_next <= IDLE;
                    end
                end
            endcase
        end
    end
