module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam [1:0] idle = 2'd0;
    localparam [1:0] s1_red = 2'd1;
    localparam [1:0] s2_yellow = 2'd2;
    localparam [1:0] s3_green = 2'd3;


    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 0)
                        state <= s3_green;
                    else
                        state <= s1_red;
                end
                s2_yellow: begin
                    if (cnt == 0)
                        state <= s1_red;
                    else
                        state <= s2_yellow;
                end
                s3_green: begin
                    if (cnt == 0)
                        state <= s2_yellow;
                    else
                        state <= s3_green;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (green && !p_green) begin
                cnt <= 8'd60;
            end else if (yellow && !p_yellow) begin
                cnt <= 8'd5;
            end else if (red && !p_red) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 8'd1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clock <= 8'd10;
        end else begin
            clock <= cnt;
        end
    end


    always @(*) begin
        case (state)
            idle: begin
                p_red = 1'b0;
                p_yellow = 1'b0;
                p_green = 1'b0;
            end
            s1_red: begin
                p_red = 1'b1;
                p_yellow = 1'b0;
                p_green = 1'b0;
            end
            s2_yellow: begin
                p_red = 1'b0;
                p_yellow = 1'b1;
                p_green = 1'b0;
            end
            s3_green: begin
                p_red = 1'b0;
                p_yellow = 1'b0;
                p_green = 1'b1;
            end
            default: begin
                p_red = 1'b0;
                p_yellow = 1'b0;
                p_green = 1'b0;
            end
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

endmodule

