module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg sign_dividend;
    reg sign_divisor;
    reg [3:0] cnt;
    reg start_cnt;
    reg [16:0] SR;

    reg [7:0] divisor_abs;
    reg [8:0] NEG_DIVISOR;

    wire [8:0] remainder_upper = SR[16:8];
    wire [7:0] quotient_part = SR[7:0];
    wire carry_out = (remainder_upper >= {1'b0, abs_divisor});

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            divisor_abs <= 0;
            NEG_DIVISOR <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_dividend <= sign ? dividend[7] : 1'b0;
                sign_divisor <= sign ? divisor[7] : 1'b0;
                if (sign) begin
                    abs_dividend <= (dividend[7]) ? (-dividend) : dividend;
                    abs_divisor <= (divisor[7]) ? (-divisor) : divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end

                SR <= {abs_dividend, 1'b0};
                NEG_DIVISOR <= -{1'b0, abs_divisor};

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    if (carry_out) begin
                        SR[16:8] <= remainder_upper + {1'b0, abs_divisor};
                        SR[0] <= 1'b1;

                    end else begin
                        SR[0] <= 1'b0;
                    end

                    SR <= SR << 1;
                    cnt <= cnt + 1;
                end else begin

                    start_cnt <= 0;

                    if (sign) begin

                        if (sign_dividend ^ sign_divisor)
                            result[7:0] <= ~quotient_part + 1;
                        else
                            result[7:0] <= quotient_part;

                        if (sign_dividend)
                            result[15:8] <= ~SR[16:9] + 1;
                        else
                            result[15:8] <= SR[16:9];
                    end else begin
                        result <= {SR[16:9], quotient_part};
                    end
                    res_valid <= 1;
                end
            end else begin
                res_valid <= 0;
            end
        end
    end
endmodule

