module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);
    reg [15:0] a_reg, b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        reg [15:0] quotient;
        reg [7:0] remainder;
        integer i;

        quotient = 16'b0;
        remainder = a_reg[15:8];

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            if (i == 15) begin

                if (remainder >= b_reg) begin
                    quotient[i] = 1'b1;
                    remainder = remainder - b_reg;
                end else begin
                    quotient[i] = 1'b0;
                end
            end else begin

                remainder = {remainder[6:0], a_reg[7 - (15 - i)]};
                if (remainder >= b_reg) begin
                    quotient[i] = 1'b1;
                    remainder = remainder - b_reg;
                end else begin
                    quotient[i] = 1'b0;
                end
            end
        end

        odd = {8'b0, remainder};
        result = quotient;
    end
endmodule

