                areg <= ain;
                breg <= bin;
            end


            if (i > 5'b0 && i < 5'd17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end


            case (i)
                5'd16: done_r <= 1'b1;
                5'd17: done_r <= 1'b0;
                default: done_r <= done_r;
            endcase
        end
    end


