module adder_bcd (A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    wire [4:0] sum_bin = {1'b0, A} + {1'b0, B} + Cin;
    wire [3:0] sum_corrected;
    wire carry;

    assign sum_corrected = (sum_bin > 9) ? (sum_bin[3:0] + 4'd6) : sum_bin[3:0];
    assign carry = (sum_bin > 9);

    assign Sum = sum_corrected;
    assign Cout = carry;

endmodule

