module fixed_point_adder #(parameter Q = 3, parameter N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    reg sign_res;
    reg [N-1:0] mag;
    reg [N:0] sum_abs;

    always @* begin
        if (sign_a == sign_b) begin
            sum_abs = abs_a + abs_b;
            if (sum_abs > (2**(N-1) - 1)) begin
                mag = (1 << (N-1)) - 1;
            end else begin
                mag = sum_abs[N-1:0];
            end
            res = {sign_a, mag};
        end else begin
            if (abs_a > abs_b) begin
                mag = abs_a - abs_b;
                sign_res = sign_a;
            end else if (abs_b > abs_a) begin
                mag = abs_b - abs_a;
                sign_res = sign_b;
            end else begin
                mag = 0;
                sign_res = 0;
            end
            res = {sign_res, mag};
        end
        c = res;
    end
endmodule

