module fixed_point_subtractor #(parameter Q=3, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] sum;

    always @* begin
        a_abs = a_sign ? (-a) : a;
        b_abs = b_sign ? (-b) : b;

        if (same_sign) begin
            res = a - b;
            res[N-1] = a_sign;
        end else begin
            if (a_sign == 0 && b_sign == 1) begin
                sum = a_abs + b_abs;
                if (a_abs > b_abs) begin
                    res = sum;
                    res[N-1] = 0;
                end else begin
                    res = b_abs - a_abs;
                    res[N-1] = 1;
                end
            end else begin
                sum = a_abs + b_abs;
                if (a_abs > b_abs) begin
                    res = -sum;
                    res[N-1] = 1;
                end else begin
                    res = sum;
                    res[N-1] = 0;
                end
            end
        end


        if (res == 0) begin
            res[N-1] = 0;
        end

        c = res;
    end
endmodule

