module float_multi(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'h0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            z_exponent <= 8'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            z_mantissa <= 23'b0;
            product <= 48'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a_exponent == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b_exponent == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= a_exponent + b_exponent - 8'd127;


                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (a_exponent == 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (b_exponent == 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (a_exponent == 8'h00 && b_exponent == 8'h00) begin
                        z <= {z_sign, 31'h0};
                    end else if (a_exponent == 8'h00) begin
                        z <= {z_sign, 31'h0};
                    end else if (b_exponent == 8'h00) begin
                        z <= {z_sign, 31'h0};
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b001: begin

                    product <= {24'b0, a_mantissa} * {24'b0, b_mantissa};
                    counter <= counter + 1;
                end
                3'b010: begin

                    if (product[47:46] >= 2) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    z_mantissa <= product[46:23];
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    counter <= counter + 1;
                end
                3'b011: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                    end else if (guard_bit && ~round_bit && ~sticky) begin
                        if (z_mantissa[0])
                            z_mantissa <= z_mantissa + 1;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (z_exponent >= 8'hfe) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent == 8'h00) begin
                        z <= {z_sign, 31'h0};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end
endmodule

