module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);
    wire signed [63:0] signed_A = A;
    wire signed [63:0] signed_B = B;
    wire signed [63:0] signed_result = signed_A - signed_B;

    assign result = signed_result;

    wire A_positive = ~signed_A[63];
    wire B_negative = signed_B[63];
    wire result_negative = signed_result[63];
    wire positive_overflow = A_positive & B_negative & result_negative;

    wire A_negative = signed_A[63];
    wire B_positive = ~signed_B[63];
    wire result_positive = ~signed_result[63];
    wire negative_overflow = A_negative & B_positive & result_positive;

    assign overflow = positive_overflow | negative_overflow;
endmodule

