module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);
    parameter S0 = 3'd0,
              S1 = 3'd1,
              S2 = 3'd2,
              S3 = 3'd3,
              S4 = 3'd4;

    reg [2:0] state, next_state;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            S0: next_state = IN ? S1 : S0;
            S1: next_state = (IN == 0) ? S2 : S1;
            S2: next_state = (IN == 0) ? S3 : S1;
            S3: next_state = (IN == 1) ? S4 : S1;
            S4: next_state = (IN == 1) ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    always @(*) begin
        if (RST)
            MATCH = 1'b0;
        else
            MATCH = (state == S4) && (IN == 1'b1);
    end
