    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case(state)
                idle: state <= s1_red;
                s1_red: if (cnt == 0) state <= s3_green;
