module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;


reg [32:0] res_temp;

reg [31:0] res;


assign zero = (r == 32'b0);


always @* begin
    case (aluc)
        SLT: flag = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
        SLTU: flag = (a < b) ? 1'b1 : 1'b0;
        default: flag = 1'bz;
    endcase
end


always @* begin
    res = 32'b0;
    carry = 1'b0;
    overflow = 1'b0;
    case (aluc)
        ADD: begin
            res_temp = {a[31], a} + {b[31], b};
            res = res_temp[31:0];
            carry = res_temp[32];
            overflow = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
        end
        ADDU: begin
            res = a + b;
            carry = res[32];



            res_temp = {1'b0, a} + {1'b0, b};
            res = res_temp[31:0];
            carry = res_temp[32];
        end
