module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg sign_reg;
    reg [7:0] absolute_dividend, absolute_divisor;
    reg sign_dividend, sign_divisor;
    reg [7:0] NEG_DIVISOR;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg processing;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_reg <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            absolute_dividend <= 0;
            absolute_divisor <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (!res_valid) begin
                if (opn_valid) begin
                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                    sign_reg <= sign;
                    if (sign) begin
                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        absolute_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                        absolute_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    end else begin
                        sign_dividend <= 0;
                        sign_divisor <= 0;
                        absolute_dividend <= dividend;
                        absolute_divisor <= divisor;
                    end
                    SR <= {absolute_dividend, 1'b0} << 1;
                    NEG_DIVISOR <= -absolute_divisor;
                    cnt <= 4'd1;
                    processing <= 1;
                    res_valid <= 0;
                end else if (processing) begin
                    if (cnt < 4'd8) begin
                        reg [8:0] sub_result;
                        reg carry_out;
                        sub_result = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                        carry_out = ~sub_result[8];
                        SR <= (carry_out) ? {sub_result[7:0], SR[7:0] << 1 | 1'b1} : {SR[15:8], SR[7:0] << 1};
                        cnt <= cnt + 4'd1;
                    end else begin
                        processing <= 0;
                        res_valid <= 1;
                        if (sign_reg) begin
                            reg [7:0] q = SR[7:0];
                            reg [7:0] r = SR[15:8];
                            reg q_sign = sign_dividend ^ sign_divisor;
                            reg r_sign = sign_dividend;
                            if (q_sign) q = ~q + 1;
                            if (r_sign && r != 0) r = ~r + 1;
                            result <= {r, q};
                        end else result <= SR;
                    end
                end
            end else res_valid <= 0;
        end
    end
endmodule

