module comparator_4bit (A, B, A_greater, A_equal, A_less);
    input [3:0] A, B;
    output A_greater, A_equal, A_less;

    wire [4:0] sum;
    assign sum = {1'b0, A} + {1'b0, ~B} + 5'd1;

    wire carry_out = sum[4];

    wire [3:0] sub_result = sum[3:0];


    assign A_equal = (sub_result == 4'b0000);

    assign A_less = ~carry_out;

    assign A_greater = carry_out & ~A_equal;


