module cla16bit(
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G,
    output P,
    output C_out
);
    wire [16:1] g, p, c;


    assign c[1] = C_in;
    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin: gen_gp
            assign g[i] = A[i] & B[i];
            assign p[i] = A[i] ^ B[i];
        end
    endgenerate


    generate
        genvar j;
        for (j = 1;
 j <= 16;
 j = j + 1) begin: carry
            if (j == 1) begin
                assign c[j+1] = g[j];
            end else begin
                assign c[j+1] = g[j] | (p[j] & c[j]);
            end
        end
    endgenerate


    assign S = p ^ c[16:1];


    wire [16:1] G_terms, P_terms;
    assign G_terms[1] = g[1];
    assign P_terms[1] = p[1];
    generate
        genvar k;
        for (k = 2;
 k <= 16;
 k = k + 1) begin: gp_terms
            assign G_terms[k] = g[k] | (P_terms[k-1] & G_terms[k-1]);
            assign P_terms[k] = P_terms[k-1] & p[k];
        end
    endgenerate


    assign G = G_terms[16];
    assign P = P_terms[16];
    assign C_out = G | (P & C_in);
