module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
reg [N-1:0] res;
wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;

always @* begin
    if (a[N-1] == b[N-1]) begin

        res = a + b;

        if (res[N-1] != a[N-1]) begin

            if (a[N-1]) begin

                res = {1'b1, {N-1{1'b0}}};
            end else begin

                res = {1'b0, {N-1{1'b1}}};
            end
        end
    end else begin

        if (abs_a > abs_b) begin
            res = a - b;
        end else begin
            res = b - a;
        end
    end
end

assign c = res;

endmodule

