module fixed_point_subtractor #(
    parameter Q = 16,
    parameter N = 32
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-2:0] a_mag, b_mag;
    wire [N-1:0] a_abs, b_abs;
    wire [N:0] sum_mag;

    wire [N-2:0] sum_mag_truncated;
    wire sign_res;

    always @* begin
        if (same_sign) begin
            res = a - b;
            if (res == 0)
                res[N-1] = 0;

        end else begin
            a_abs = sign_a ? (~a + 1) : a;
            b_abs = sign_b ? (~b + 1) : b;
            sum_mag = a_abs + b_abs;
            if (a_abs > b_abs)
                sign_res = sign_a;
            else
                sign_res = ~sign_a;
            if (sum_mag == 0)
                sign_res = 0;

            res = {sign_res, sum_mag[N-2:0]};
        end
    end

    assign c = res;

endmodule

