module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

always @* begin
    result = $signed(A) - $signed(B);
    overflow = (~A[63] & B[63] & result[63]) | 
               (A[63] & ~B[63] & ~result[63]);
end

endmodule

