module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    reg [3:0] waddr_bin, raddr_bin;
    reg [3:0] wptr, rptr;
    wire [3:0] wptr_next, rptr_next;
    wire wen, ren;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    assign wptr_next = (waddr_bin + 1) ^ ((waddr_bin + 1) >> 1);
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            waddr_bin <= 0;
            wptr <= 0;
        end else if (wen) begin
            waddr_bin <= waddr_bin + 1;
            wptr <= wptr_next;
        end
    end


    assign rptr_next = (raddr_bin + 1) ^ ((raddr_bin + 1) >> 1);
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            raddr_bin <= 0;
            rptr <= 0;
        end else if (ren) begin
            raddr_bin <= raddr_bin + 1;
            rptr <= rptr_next;
        end
    end


    reg [3:0] rptr_sync1, rptr_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            rptr_sync1 <= 0;
            rptr_sync2 <= 0;
        end else begin
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end
    wire [3:0] rptr_syn = rptr_sync2;


    reg [3:0] wptr_sync1, wptr_sync2;
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            wptr_sync1 <= 0;
            wptr_sync2 <= 0;
        end else begin
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end
    wire [3:0] wptr_syn = wptr_sync2;


    assign rempty = (rptr == wptr_syn);
    assign wfull = (wptr[3] != rptr_syn[3]) && (wptr[2] != rptr_syn[2]) && (wptr[1:0] == rptr_syn[1:0]);


    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

endmodule


