module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    assign EMPTY = (SP == 3'd4);
    assign FULL = (SP == 3'd0);

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 3'd4;
            stack_mem[0] <= 4'd0;
            stack_mem[1] <= 4'd0;
            stack_mem[2] <= 4'd0;
            stack_mem[3] <= 4'd0;
            dataOut <= 4'd0;
        end else begin
            if (EN) begin
                case (RW)
                    1'b0: begin 
                        if (~FULL) begin
                            stack_mem[SP - 1] <= dataIn;
                            SP <= SP - 1;
                        end
                    end
                    1'b1: begin 
                        if (~EMPTY) begin
                            dataOut <= stack_mem[SP];
                            stack_mem[SP] <= 4'd0;
                            SP <= SP + 1;
                        end
                    end
                endcase
            end
        end
    end
endmodule

