        if (~rst_n) begin
            state <= State0;
            data_out <= 0;
        end else begin
            case (state)
                State0: begin
                    if (data_in) begin
                        state <= State1;
                    end else begin
                        state <= State0;
                    end
                    data_out <= 0;
                end
                State1: begin
                    if (data_in == 0) begin
                        data_out <= 1;
                        state <= State0;
                    end else begin
                        data_out <= 0;
                        state <= State0;
                    end
                end
            endcase
        end
    end
