module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg [7:0] neg_divisor;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        neg_divisor <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                dividend_abs <= dividend[7] ? -dividend : dividend;
                divisor_abs <= divisor[7] ? -divisor : divisor;
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
            end
            neg_divisor <= -divisor_abs;

            SR <= {dividend_abs, 1'b0};

            start_cnt <= 1;
            cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt && !res_valid) begin
            if (cnt == 8) begin

                result <= {SR[15:8], SR[7:0]};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin

                wire [8:0] temp = {1'b0, SR[15:8]} - neg_divisor;
                wire carry = temp[8];
                if (carry) begin

                    SR[15:8] <= temp[7:0];
                    SR[7:0] <= {SR[7:0], 1'b1};
                end else begin

                    SR[7:0] <= {SR[7:0], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

