module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        reg [15:0] dividend = a_reg;
        reg [7:0] divisor = b_reg;
        reg [15:0] rem = 16'b0;
        reg [15:0] quo = 16'b0;

        for (int i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((dividend >> i) & 1);
            if (rem >= divisor) begin
                quo[i] = 1'b1;
                rem = rem - divisor;
            end else begin
                quo[i] = 1'b0;
            end
        end

        result = quo;
        odd = rem;

    end
endmodule

