module fixed_point_adder #(parameter Q = 4, parameter N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire same_sign = (a[N-1] == b[N-1]);
    wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;
    wire [N-1:0] magnitude_sub;

    always @* begin
        if (same_sign) begin
            res = a + b;
            res[N-1] = a[N-1];
        end else begin
            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = 0;
            end else begin
                magnitude_sub = abs_b - abs_a;
                res = ~magnitude_sub + 1;
                res[N-1] = 1;
            end
        end
        c = res;
    end

endmodule

