module fixed_point_subtractor #(parameter Q=3, N=8) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b, sign_res;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        res = a - b;
        sign_res = sign_a;

        if (sign_a != sign_b) begin

            if (sign_a) begin 
                if (a >= ~b + 1) begin 
                    res = (a >= ~b + 1) ? (a - (~b + 1)) : ( (~b + 1) - a );
                    sign_res = 1;
                end else begin
                    res = (~b + 1) - a;
                    sign_res = 0;
                end
            end else begin 
                if (b <= a) begin 
                    res = b - a;
                    sign_res = 0;
                end else begin
                    res = a - b;
                    sign_res = 1;
                end
            end
        end else begin

            if (res == 0) begin
                sign_res = 0;
            end else if (sign_res) begin

                res = -res;
                sign_res = ~sign_res;
            end
        end


        if (res == 0) begin
            sign_res = 0;
        end
        c = {sign_res, res[N-2:0]};
    end
endmodule

