module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


wire [ADDR_WIDTH-1:0] waddr, raddr;
wire [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


reg [PTR_WIDTH-1:0] rptr_sync1, rptr_sync2;
reg [PTR_WIDTH-1:0] wptr_sync1, wptr_sync2;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else begin
        if (winc && !wfull)
            wptr_bin <= wptr_bin + 1;
    end
end
assign wptr_gray = wptr_bin ^ (wptr_bin >> 1);


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else begin
        if (rinc && !rempty)
            rptr_bin <= rptr_bin + 1;
    end
end
assign rptr_gray = rptr_bin ^ (rptr_bin >> 1);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_sync1 <= 0;
        rptr_sync2 <= 0;
    end else begin
        rptr_sync1 <= rptr_gray;
        rptr_sync2 <= rptr_sync1;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_sync1 <= 0;
        wptr_sync2 <= 0;
    end else begin
        wptr_sync1 <= wptr_gray;
        wptr_sync2 <= wptr_sync1;
    end
end


assign wfull = (wptr_gray[PTR_WIDTH-1] != rptr_sync2[PTR_WIDTH-1]) &&
               (wptr_gray[PTR_WIDTH-2] != rptr_sync2[PTR_WIDTH-2]) &&
               (wptr_gray[PTR_WIDTH-3:0] == rptr_sync2[PTR_WIDTH-3:0]);
assign rempty = (rptr_gray == wptr_sync2);


wire wenc, renc;
assign wenc = winc && !wfull;
assign renc = rinc && !rempty;


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(wenc),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(renc),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);

