module LIFObuffer (
    input [3:0] dataIn,
    input RW, EN, Rst, Clk,
    output reg EMPTY, FULL,
    output reg [3:0] dataOut
);
    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];


    integer i;

    always @(posedge Clk) begin
        if (Rst) begin

            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            SP <= 3'd4;

            dataOut <= 4'b0;
            EMPTY <= 1'b1;
            FULL <= 1'b0;
        end else if (EN) begin
            if (!FULL && !RW) begin

                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end else if (RW && !EMPTY) begin

                dataOut <= stack_mem[SP];
                SP <= SP + 1;
            end

            EMPTY <= (SP == 3'd4);
            FULL <= (SP == 3'd0);
        end
    end

endmodule

