module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [1:0] cnt;

reg [3:0] data;

reg [1:0] valid_cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b0;
        data <= 4'b0;
        valid_out <= 1'b0;
        dout <= 1'b0;
        valid_cnt <= 2'b0;
    end else begin
        if (valid_out) begin
            if (valid_cnt == 2'b11) begin
                valid_out <= 1'b0;
                valid_cnt <= 2'b0;
            end else begin
                valid_cnt <= valid_cnt + 1;
            end
        end else begin
            if (cnt == 2'b11) begin 
                data <= d;
                cnt <= 2'b0;
                valid_out <= 1'b1;
                dout <= d[3];

                valid_cnt <= 2'b00;
            end else begin
                cnt <= cnt + 1;

                data <= {data[2:0], data[3]};
                dout <= data[3];

            end
        end
    end
end

endmodule

