module traffic_light(
    input        rst_n,
    input        clk,
    input        pass_request,
    output reg [7:0] clock,
    output reg   red,
    output reg   yellow,
    output reg   green
);

    parameter idle      = 2'd0;
    parameter s1_red    = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green  = 2'd3;


    reg [1:0] state, next_state;
    reg [7:0] cnt;


    reg p_red_prev, p_yellow_prev, p_green_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle: begin
                next_state = s1_red;
            end
            s1_red: begin
                if (cnt == 0)
                    next_state = s3_green;
                else
                    next_state = s1_red;
            end
            s2_yellow: begin
                if (cnt == 0)
                    next_state = s1_red;
                else
                    next_state = s2_yellow;
            end
            s3_green: begin
                if (cnt == 0)
                    next_state = s2_yellow;
                else
                    next_state = s3_green;
            end
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green && (cnt > 10)) begin
                cnt <= 10;
            end else if (!p_green && p_green_prev) begin
                cnt <= 60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red_prev    <= 0;
            p_yellow_prev <= 0;
            p_green_prev  <= 0;
        end else begin
            p_red_prev    <= red;
            p_yellow_prev <= yellow;
            p_green_prev  <= green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red    <= 0;
            yellow <= 0;
            green  <= 0;
        end else begin
            red    <= (state == s1_red);
            yellow <= (state == s2_yellow);
            green  <= (state == s3_green);
        end
    end


    assign clock = cnt;

endmodule

