module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [31:0] res;
reg [32:0] temp_sum, temp_diff;

always @(*) begin
    res = 32'bz;
    carry = 0;
    overflow = 0;
    flag = 1'bz;

    case (aluc)
        ADD: begin
            temp_sum = {1'b0, a} + {1'b0, b};
            res = temp_sum[31:0];
            carry = temp_sum[32];
            overflow = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            temp_sum = {1'b0, a} + {1'b0, b};
            res = temp_sum[31:0];
            carry = temp_sum[32];
        end
        SUB: begin
            temp_diff = {1'b0, a} - {1'b0, b};
            res = temp_diff[31:0];
            carry = temp_diff[32];
            overflow = (a[31] != b[31]) && (res[31] != a[31]);
        end
        SUBU: begin
            temp_diff = {1'b0, a} - {1'b0, b};
            res = temp_diff[31:0];
            carry = temp_diff[32];
        end
        AND:  res = a & b;
        OR:   res = a | b;
        XOR:  res = a ^ b;
        NOR:  res = ~(a | b);
        SLT:  begin
            res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            flag = ($signed(a) < $signed(b));
        end
        SLTU: begin
            res = (a < b) ? 32'd1 : 32'd0;
            flag = (a < b);
        end
        SLL:  res = b << a[4:0];
        SRL:  res = b >> a[4:0];
        SRA:  res = $signed(b) >>> a[4:0];
        SLLV: res = b << a[4:0];
