module div_16bit(A, B, result, odd);
input [15:0] A, B;
output reg [15:0] result;
output reg [15:0] odd;
reg [15:0] a_reg, b_reg;
integer i;


always @(A, B) begin
    a_reg = A;
    b_reg = B;
end


always @(A, B) begin
    reg [15:0] remainder = 16'b0;
    reg [15:0] divisor = {8'b0, b_reg};

    reg [15:0] quotient = 16'b0;
    reg [15:0] dividend = a_reg;

    for (i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = {remainder[14:0], dividend[i]};

        if (remainder >= divisor) begin
            quotient[i] = 1'b1;
            remainder = remainder - divisor;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

