module comparator_4bit(A, B, A_greater, A_equal, A_less);
  input [3:0] A, B;
  output A_greater, A_equal, A_less;
  wire [3:0] borrow;
  wire [3:0] diff;


  assign borrow[0] = (~A[0] & B[0]) | ((~A[0] | B[0]) & 1'b1);
  assign diff[0] = A[0] ^ B[0] ^ 1'b1;


  genvar i;
  generate
    for (i = 1;
 i < 4;
 i = i + 1) begin : subtractor_loop
      assign borrow[i] = (~A[i] & B[i]) | ((~A[i] | B[i]) & borrow[i-1]);
      assign diff[i] = A[i] ^ B[i] ^ borrow[i-1];
    end
  endgenerate


  assign A_less = borrow[3];
  assign A_equal = (diff == 4'b0) & ~borrow[3];
  assign A_greater = ~borrow[3] & (diff != 4'b0);
endmodule

