module fixed_point_adder #(parameter Q=3, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] difference;
    reg result_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        if (sign_a == sign_b) begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;
            res = abs_a + abs_b;
            result_sign = sign_a;
        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;
            if (abs_a > abs_b) begin
                difference = abs_a - abs_b;
                result_sign = sign_a;
            end else begin
                difference = abs_b - abs_a;
                result_sign = sign_b;
            end
            res = {result_sign, difference[N-2:0]};
        end
        c = res;
    end
endmodule

