module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if (a_exponent == 9'hff) begin
                        if (a_mantissa[0]) begin
                            z <= {a_sign ^ b_sign, 8'hff, a_mantissa[22:0]};
                            counter <= 3'b111;
                        end else if (b_exponent == 9'hff && b_mantissa[0]) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                            counter <= 3'b111;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z <= (b_exponent == 9'hff) ? {z_sign, 8'hff, 23'b0} : {z_sign, 8'hff, 23'b0};
                            counter <= 3'b111;
                        end
                    end else if (b_exponent == 9'hff) begin
                        if (b_mantissa[0]) begin
                            z <= {a_sign ^ b_sign, 8'hff, b_mantissa[22:0]};
                            counter <= 3'b111;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z <= (a_exponent == 9'hff) ? {z_sign, 8'hff, 23'b0} : {z_sign, 8'hff, 23'b0};
                            counter <= 3'b111;
                        end
                    end else begin
                        if (a_exponent == 0 && a_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                            counter <= 3'b111;
                        end else if (b_exponent == 0 && b_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                            counter <= 3'b111;
                        end else begin
                            product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                            counter <= counter + 1;
                        end
                    end
                end
                3'b010: begin

                    if (product[49]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 127;
                    end
                    product <= product[49:0];
                    counter <= counter + 1;
                end
                3'b011: begin

                    {sticky, round_bit, guard_bit} = product[11:0];
                    z_mantissa <= product[48:25];
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (guard_bit && (round_bit || sticky) || (z_mantissa[0] && round_bit)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'hffffff) begin
                            z_exponent <= z_exponent + 1;
                            z_mantissa <= 24'b0;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (z_exponent > 9'hfe) begin
                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 8'b0, 23'b0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end
endmodule

