reg [PTR_WIDTH-1:0] wptr_syn_gray0, wptr_syn_gray;
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn) begin
        wptr_syn_gray0 <= 0;
        wptr_syn_gray <= 0;
    end else begin
        wptr_syn_gray0 <= wptr_gray;
        wptr_syn_gray <= wptr_syn_gray0;
    end
end


assign rempty = (rptr_gray == wptr_syn_gray);
assign wfull = (wptr_gray[PTR_WIDTH-1] != rptr_syn_gray[PTR_WIDTH-1]) &&
               (wptr_gray[PTR_WIDTH-2] != rptr_syn_gray[PTR_WIDTH-2]) &&
               (wptr_gray[PTR_WIDTH-3:0] == rptr_syn_gray[PTR_WIDTH-3:0]);


assign waddr = waddr_bin[ADDR_WIDTH-1:0];
assign raddr = raddr_bin[ADDR_WIDTH-1:0];


dual_port_RAM #(
    .DEPTH(DEPTH),
