module parallel2serial(clk, rst_n, d, valid_out, dout);
    input clk, rst_n;
    input [3:0] d;
    output reg valid_out;
    output reg dout;

    reg [1:0] cnt;
    reg [3:0] data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            data <= 4'b0;
            valid_out <= 1'b0;
            dout <= 1'b0;
        end else begin
            case (cnt)
                2'b11: begin 
                    data <= d;
                    cnt <= 2'b00;
                    valid_out <= 1'b1;
                end
                default: begin 
                    data <= data << 1;
                    cnt <= cnt + 1;
                    valid_out <= 1'b0;
                end
            endcase

            if (cnt == 2'b11)
                dout <= d[3];
            else
                dout <= data[3];
        end
    end
endmodule

