module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg [1:0] current_state, next_state;
    parameter IDLE = 2'b00;
    parameter RISE1 = 2'b01;
    parameter FALL1 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            current_state <= IDLE;
            data_out <= 1'b0;
        end else begin
            current_state <= next_state;
            data_out <= (next_state == FALL1) ? 1'b1 : 1'b0;
        end
    end

    always @* begin
        case (current_state)
            IDLE: next_state = data_in ? RISE1 : IDLE;
            RISE1: next_state = data_in ? RISE1 : FALL1;
            FALL1: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

endmodule

