module traffic_light (
    input wire rst_n,
    input wire clk,
    input wire pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter [1:0] idle    = 2'b00,
                    s1_red  = 2'b01,
                    s2_yellow = 2'b10,
                    s3_green  = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        green <= 1;
                        red <= 0;
                    end else
                        red <= 1;
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        yellow <= 1;
                        green <= 0;
                    end else
                        green <= 1;
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        red <= 1;
                        yellow <= 0;
                    end else
                        yellow <= 1;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                cnt <= 10;
            end else begin
                case (state)
                    s1_red: cnt <= (cnt == 0) ? 10 : cnt - 1;
                    s3_green: cnt <= (cnt == 0) ? 60 : cnt - 1;
                    s2_yellow: cnt <= (cnt == 0) ? 5 : cnt - 1;
                    default: cnt <= cnt - 1;
                endcase
            end
        end
    end


    always @(*) begin
        clock = cnt;
    end
endmodule

