module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] quotient_reg, remainder_reg;
    reg [15:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg quotient_sign, remainder_sign;
    reg [8:0] temp_sum;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            quotient_reg <= 0;
            remainder_reg <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                quotient_sign <= sign ? (dividend[7] ^ divisor[7]) : 0;
                remainder_sign <= sign ? dividend[7] : 0;

                SR <= {abs_dividend, 8'b0} << 1;

                start_cnt <= 1;
                cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    if (quotient_sign) quotient_reg <= -quotient_reg;
                    if (remainder_sign) remainder_reg <= -remainder_reg;
                    result <= {remainder_reg, quotient_reg};
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    SR <= SR << 1;
                    temp_sum = {1'b0, SR[15:8]} + {1'b0, abs_divisor};
                    if (temp_sum[8] == 0) begin
                        SR[15:8] <= temp_sum[7:0];
                        quotient_reg <= {quotient_reg[6:0], 1'b1};
                    end else begin
                        quotient_reg <= {quotient_reg[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end
endmodule

