module div_16bit(A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result;
output reg [15:0] odd;

reg [15:0] a_reg, b_reg;

always @(A or B) begin
    a_reg = A;
    b_reg = B;
end

always @(A or B) begin
    reg [15:0] quotient;
    reg [15:0] remainder;
    integer i;

    quotient = 16'b0;
    remainder = {8'b0, a_reg[15:8]};


    if (remainder[15:8] >= b_reg) begin
        remainder[15:8] = remainder[15:8] - b_reg;
        quotient[15] = 1'b1;
    end


    remainder = {remainder[15:8], a_reg[7:0]};
    if (remainder >= {8'b0, b_reg}) begin
        remainder = remainder - {8'b0, b_reg};
        quotient[14] = 1'b1;
    end

    result = quotient;
    odd = remainder;
end

endmodule

