module adder_bcd(A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output reg [3:0] Sum;
    output reg Cout;

    wire [4:0] binary_sum;
    assign binary_sum = {1'b0, A} + {1'b0, B} + {4'b0, Cin};

    always @(*) begin
        if (binary_sum > 9) begin
            Sum = binary_sum - 5'd6;
            Cout = 1'b1;
        end else begin
            Sum = binary_sum[3:0];
            Cout = 1'b0;
        end
    end
endmodule

