module fixed_point_adder #(parameter Q=3, N=5) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-2:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-2:0] b_abs = b_sign ? (~b + 1) : b;
    wire [N-2:0] sum_abs;
    wire result_sign;

    always @(*) begin
        if (a_sign == b_sign) begin
            sum_abs = a_abs + b_abs;
            result_sign = a_sign;
        end else begin
            if (a_abs > b_abs) begin
                sum_abs = a_abs - b_abs;
                result_sign = 1'b0;
            end else if (b_abs > a_abs) begin
                sum_abs = b_abs - a_abs;
                result_sign = 1'b1;
            end else begin
                sum_abs = {N-1{1'b0}};
                result_sign = 1'b0;
            end
        end
        res = {result_sign, sum_abs};
        c = res;
    end
endmodule

