module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] a_mag = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_mag = sign_b ? (~b + 1) : b;
    wire [N-1:0] sum_mag = a_mag + b_mag;

    always @* begin
        if (sign_a == sign_b) begin
            res = a - b;
            if (res == 0)
                res = 0;
            else
                res[N-1] = sign_a;
        end else begin
            if (a_mag > b_mag) begin
                res = sum_mag;
                res[N-1] = sign_a;
            end else begin
                res = -sum_mag;
                res[N-1] = sign_a;
            end
        end
    end

    always @* begin
        c = res;
    end

endmodule

