        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};


                    if ((a_exponent == 8'hFF && |a[22:0]) || 
                        (b_exponent == 8'hFF && |b[22:0])) begin
                        z <= {1'b0, 8'hFF, 23'h1};
                        counter <= 3'b000;
                    end

                    else if ((a_exponent == 8'hFF && a_mantissa == 0) || 
                             (b_exponent == 8'hFF && b_mantissa == 0)) begin
                        if (a_exponent == 8'hFF && a_mantissa == 0 && 
                            b_exponent == 8'hFF && b_mantissa != 0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end else if (b_exponent == 8'hFF && b_mantissa == 0 && 
                                   a_exponent == 8'hFF && a_mantissa != 0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end else begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end
                        counter <= 3'b000;
                    end

                    else if ((a_exponent == 8'h00 && a_mantissa == 0) || 
                             (b_exponent == 8'h00 && b_mantissa == 0)) begin
                        if (a_exponent == 8'h00 && a_mantissa == 0 && 
                            b_exponent == 8'h00 && b_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 8'h00, 23'h0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'h00, 23'h0};
                        end
                        counter <= 3'b000;
                    end

                    else begin
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent;
                        z_sign <= a_sign ^ b_sign;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    z_mantissa <= product[46:24];
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 3'b010;
