                3'b010: begin

                    if (guard_bit && (round_bit || sticky) || 
                        (guard_bit && !round_bit && !sticky && z_mantissa[0])) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 23'h7FFFFF) begin 
                            product <= product << 1;
                            z_exponent <= z_exponent + 1;
                        end
                    end

                    if (z_exponent >= 255) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if (z_exponent[9] || z_exponent == 0) begin
                        z <= {z_sign, 8'h00, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end
