        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr),
        .wdata(wdata),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );


    reg [PTR_BITS-1:0] waddr_bin;
    wire [PTR_BITS-1:0] wptr;
    reg [PTR_BITS-1:0] rptr_sync1, rptr_sync;


    reg [PTR_BITS-1:0] raddr_bin;
    wire [PTR_BITS-1:0] rptr;
    reg [PTR_BITS-1:0] wptr_sync1, wptr_sync;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync1 <= 0;
            rptr_sync <= 0;
        end else begin
            rptr_sync1 <= rptr;
            rptr_sync <= rptr_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync1 <= 0;
            wptr_sync <= 0;
        end else begin
            wptr_sync1 <= wptr;
            wptr_sync <= wptr_sync1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else if (wenc) begin
            waddr_bin <= waddr_bin + 1;
        end
    end

    assign wptr = (waddr_bin >> 1) ^ waddr_bin;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else if (ren) begin
            raddr_bin <= raddr_bin + 1;
        end
