                       (wptr[PTR_BITS-2] != rptr_sync[PTR_BITS-2]) &&
                       (wptr[PTR_BITS-3:0] == rptr_sync[PTR_BITS-3:0]);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull <= 0;
