module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] SP;

    reg [3:0] stack_mem [0:3];

    integer i;

    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin

                SP <= 4;
                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 0;
                EMPTY <= 1;
                FULL <= 0;
            end else begin

                reg [3:0] next_SP = SP;
                reg [3:0] next_dataOut = dataOut;
                reg [3:0] next_stack_mem [0:3] = stack_mem;


                next_dataOut = dataOut;
                next_stack_mem = stack_mem;


                if (RW == 0 && !FULL) begin
                    next_stack_mem[SP - 1] = dataIn;
                    next_SP = SP - 1;
                end 

                else if (RW == 1 && !EMPTY) begin
                    next_dataOut = stack_mem[SP];
                    next_SP = SP + 1;
                    next_stack_mem[SP] = 0;
                end


                SP <= next_SP;
                dataOut <= next_dataOut;
                stack_mem <= next_stack_mem;


                EMPTY <= (next_SP == 4);
                FULL <= (next_SP == 0);
            end
        end
    end
endmodule

