module radix2_div (
    input               clk,
    input               rst,
    input               sign,
    input       [7:0]   dividend,
    input       [7:0]   divisor,
    input               opn_valid,
    output reg          res_valid,
    output reg  [15:0]  result
);
    reg [7:0] dividend_abs, divisor_abs, NEG_DIVISOR;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    wire [8:0] sub_result;
    wire carry_out;

    assign sub_result = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
    assign carry_out = sub_result[8];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            NEG_DIVISOR <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -divisor_abs;
                SR <= {8'b0, dividend_abs} << 1;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin
                    if (carry_out) begin
                        SR[15:8] <= sub_result[7:0];
                    end
                    SR <= {SR[14:0], carry_out};
                    cnt <= cnt + 1;
                    if (cnt == 8) begin
                        start_cnt <= 0;
                        res_valid <= 1;
                        result <= SR;
                    end
                end
            end
            if (start_cnt == 0 && cnt == 8) begin
                result <= SR;
            end
        end
    end
endmodule

