module div_16bit (A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg, b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(A, B) begin
        reg [15:0] dividend = a_reg;
        reg [15:0] divisor = b_reg;
        reg [15:0] rem = 16'b0;
        reg [15:0] quotient = 16'b0;

        for (int i = 15;
 i >= 0;
 i = i - 1) begin
            rem = rem << 1;
            rem[0] = dividend[i];
            if (rem >= divisor) begin
                rem = rem - divisor;
                quotient[i] = 1'b1;
            end
        end

        result = quotient;
        odd = rem;
    end
endmodule

