module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output P,
    output G
);
    wire [16:1] G_i, P_i;
    wire [16:1] C;

    assign P_i = A ^ B;

    assign G_i = A & B;



    assign C[1] = G_i[1] | (P_i[1] & Cin);

    genvar i;
    generate
        for (i = 2;
 i <= 16;
 i = i + 1) begin : carry
            wire temp;
            assign temp = G_i[i] | (P_i[i] & G_i[i-1]);
            assign C[i] = temp | (P_i[i] & P_i[i-1] & C[i-1]);
        end
    endgenerate


    assign S = P_i ^ C;


    assign P = &P_i;

    assign G = G_i[16] | (P_i[16] & G_i[15]);

endmodule

