module fixed_point_adder #(parameter Q, parameter N) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-1:0] a_abs = sign_a ? (-a) : a;
wire [N-1:0] b_abs = sign_b ? (-b) : b;

always @* begin
    if (sign_a == sign_b) begin
        res = a + b;
    end else begin
        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
        end else if (b_abs > a_abs) begin
            res = b_abs - a_abs;
        end else begin
            res = 0;
        end
    end
end

reg sign_res;
always @* begin
    if (sign_a == sign_b) begin
        sign_res = sign_a;
    end else begin
        if (a_abs > b_abs) begin
            sign_res = sign_a;
        end else if (b_abs > a_abs) begin
            sign_res = sign_b;
        end else begin
            sign_res = 0;
        end
    end
end

reg [N-1:0] res_shifted;
always @* begin
    res_shifted = res >> Q;
end

always @* begin
    c = {sign_res, res_shifted[N-2:0]};
end

endmodule

