module fixed_point_subtractor #(parameter Q=8, N=16) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;

    always @* begin
        if (a[N-1] == b[N-1]) begin

            res = a - b;

            if (res == 0)
                res[N-1] = 0;
        end else begin

            reg [N-1:0] a_abs, b_abs;
            a_abs = a[N-1] ? (-a) : a;
            b_abs = b[N-1] ? (-b) : b;
            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
                res[N-1] = 0;

            end else begin
                res = b_abs - a_abs;
                res[N-1] = 1;

            end

            if (res == 0)
                res[N-1] = 0;
        end
        c = res;
    end
endmodule

