module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    function is_nan(input [31:0] x);
        is_nan = (x[30:23] == 8'hff) && (x[22:0] != 23'b0);
    endfunction

    function is_inf(input [31:0] x);
        is_inf = (x[30:23] == 8'hff) && (x[22:0] == 23'b0);
    endfunction

    function is_zero(input [31:0] x);
        is_zero = (x[30:23] == 8'h00) && (x[22:0] == 23'b0);
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 9'b0;
            b_exponent <= 9'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            product <= 48'b0;
            z_mantissa <= 24'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            z_exponent <= 9'b0;
        end else begin
            case (counter)
                3'd0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'h00 && a[22:0] == 23'b0) ? 24'b0 : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'h00 && b[22:0] == 23'b0) ? 24'b0 : {1'b1, b[22:0]};
                    counter <= 3'd1;
                end
                3'd1: begin
                    if (is_nan(a) || is_nan(b)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= 3'd4;
                    end else if (is_inf(a) || is_inf(b)) begin
                        if ((is_zero(a) && is_inf(b)) || (is_zero(b) && is_inf(a))) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end
                        counter <= 3'd4;
                    end else if (is_zero(a) || is_zero(b)) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'b0};
                        counter <= 3'd4;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        counter <= 3'd2;
                    end
                end
                3'd2: begin
