module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [1:0] cnt;

reg [3:0] data;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin

        cnt <= 2'b0;
        data <= 4'b0;
        valid_out <= 1'b0;
    end else begin
        if (cnt == 2'd3) begin

            data <= d;
            cnt <= 2'd0;
            valid_out <= 1'b1;
        end else begin

            data <= data << 1;
            cnt <= cnt + 2'd1;
            valid_out <= 1'b0;
        end
    end
end


always @* begin
    dout = valid_out ? data[3] : 1'b0;
end

endmodule

