    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state_reg <= 1'b0;
            data_out <= 1'b0;
        end else begin
            case (state_reg)
                1'b0: begin 
                    if (data_in) begin
                        state_reg <= 1'b1;
                        data_out <= 1'b0;
                    end else begin
                        state_reg <= 1'b0;
                        data_out <= 1'b0;
                    end
