                1'b1: begin 
                    if (~data_in) begin
                        state_reg <= 1'b0;
                        data_out <= 1'b1;
                    end else begin
                        state_reg <= 1'b1;
                        data_out <= 1'b0;
                    end
                end
            endcase
        end
    end

