module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            cnt <= 10;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 10;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request) begin
                        if (cnt > 10)
                            cnt <= 10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 5;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase

            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            red <= (state == s1_red);
            yellow <= (state == s2_yellow);
            green <= (state == s3_green);
            clock <= cnt;
        end
    end
endmodule

