module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg hold;
reg processing_occurred;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_lock <= 8'b0;
        hold <= 1'b0;
        processing_occurred <= 1'b0;
        data_out <= 16'b0;
        valid_out <= 1'b0;
    end else begin
        processing_occurred <= 1'b0;
        valid_out <= processing_occurred;

        if (valid_in) begin
            if (hold) begin
                data_out <= {data_lock, data_in};
                hold <= 1'b0;
                processing_occurred <= 1'b1;
            end else begin
                data_lock <= data_in;
                hold <= 1'b1;
            end
        end
    end
end

endmodule

