module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend, saved_divisor;
reg [7:0] absolute_dividend, absolute_divisor;
reg dividend_sign, divisor_sign;
reg [3:0] cnt;
reg start_cnt;
reg [15:0] SR;
reg [8:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        saved_dividend <= 0;
        saved_divisor <= 0;
        absolute_dividend <= 0;
        absolute_divisor <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (start_cnt) begin
            if (cnt < 8) begin
                reg [8:0] subtract_result;
                reg [7:0] remainder;
                reg quotient_bit;
                subtract_result = {1'b0, SR[15:8]} - NEG_DIVISOR;
                if (subtract_result[8]) begin
                    remainder = SR[15:8];
                    quotient_bit = 0;
                end else begin
                    remainder = subtract_result[7:0];
                    quotient_bit = 1;
                end
                SR <= (SR << 1) | {15'b0, quotient_bit};
                cnt <= cnt + 1;
            end else begin
                start_cnt <= 0;
                cnt <= 0;
                reg [7:0] quotient = SR[7:0];
                reg [7:0] remainder = SR[15:8];
                if (sign) begin
                    quotient = (dividend_sign ^ divisor_sign) ? (~quotient + 1) : quotient;
                    remainder = dividend_sign ? (~remainder + 1) : remainder;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
            end
        end else if (opn_valid && !res_valid) begin
            saved_dividend <= dividend;
            saved_divisor <= divisor;
            if (sign) begin
                dividend_sign <= saved_dividend[7];
                divisor_sign <= saved_divisor[7];
                absolute_dividend <= saved_dividend[7] ? (~saved_dividend + 1) : saved_dividend;
                absolute_divisor <= saved_divisor[7] ? (~saved_divisor + 1) : saved_divisor;
            end else begin
                dividend_sign <= 0;
                divisor_sign <= 0;
                absolute_dividend <= saved_dividend;
                absolute_divisor <= saved_divisor;
            end
            SR <= {absolute_dividend << 1, 8'b0};
            NEG_DIVISOR <= {1'b0, absolute_divisor} + 1;
            start_cnt <= 1;
            cnt <= 1;
            res_valid <= 0;
        end else begin
            res_valid <= res_valid && !opn_valid;
        end
    end
end

endmodule

