module div_16bit(A, B, result, odd);
input [15:0] A, B;
output reg [15:0] result, odd;

reg [15:0] a_reg, b_reg;


always @(A or B) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    result = 0;
    odd = 0;
    reg [31:0] temp;

    temp = {16'b0, a_reg};

    for (integer i = 15;
 i >= 0;
 i = i - 1) begin

        temp = temp << 1;
        if (temp[31:16] >= b_reg) begin
            temp[31:16] = temp[31:16] - b_reg;
            result[i] = 1;
        end
    end
    odd = temp[15:0];

end

endmodule

