module comparator_4bit(A, B, A_greater, A_equal, A_less);
  input [3:0] A, B;
  output A_greater, A_equal, A_less;

  wire [4:0] sub_result;
  wire borrow_out;

  assign sub_result = {1'b0, A} - {1'b0, B};
  assign borrow_out = sub_result[4];

  assign A_less = borrow_out;
  assign A_equal = (sub_result[3:0] == 4'b0) && ~borrow_out;
  assign A_greater = (sub_result[3:0] != 4'b0) && ~borrow_out;

