module adder_bcd (A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    reg [4:0] sum_bin;
    reg [3:0] sum_bcd;
    reg carry;

    always @* begin
        sum_bin = A + B + Cin;
        if (sum_bin > 9) begin
            sum_bcd = (sum_bin + 6) % 10;
            carry = 1'b1;
        end else begin
            sum_bcd = sum_bin[3:0];
            carry = 1'b0;
        end
    end

    assign Sum = sum_bcd;
    assign Cout = carry;
endmodule

