                count_next = count + 1;
            end


            if (count_next == 4) begin
                data_out <= sum_next;
                valid_out <= 1'd1;
                sum_reg <= 10'd0;
                count <= 3'd0;
            end else begin
                sum_reg <= sum_next;
                count <= count_next;
            end
        end
    end
