module fixed_point_adder #(parameter Q = 2, parameter N = 4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    always @* begin
        reg a_sign, b_sign;
        reg [N-1:0] a_abs, b_abs;
        reg [N-1:0] res_temp;
        reg res_sign;
        reg a_gt_b_abs;

        a_sign = a[N-1];
        b_sign = b[N-1];
        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;
        a_gt_b_abs = (a_abs > b_abs);

        if (a_sign == b_sign) begin
            res_temp = a_abs + b_abs;
            res_sign = a_sign;
        end else begin
            if (a_gt_b_abs) begin
                res_temp = a_abs - b_abs;
                res_sign = 1'b0;
            end else if (b_abs > a_abs) begin
                res_temp = b_abs - a_abs;
                res_sign = 1'b1;
            end else begin
                res_temp = {N{1'b0}};
                res_sign = 1'b0;
            end
        end

        res = {res_sign, res_temp[N-2:0]};
    end

    assign c = res;
endmodule

