module fixed_point_subtractor #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg signed [N-1:0] a_signed, b_signed;
    reg signed [N-1:0] temp_res;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        a_signed = a;
        b_signed = b;

        if (sign_a == sign_b) begin

            temp_res = a_signed - b_signed;
            res = temp_res;


            if (res == 0)
                res[N-1] = 1'b0;
        end else begin

            if (sign_a == 1'b0) begin

                temp_res = a_signed - b_signed;
                if (a_signed > b_signed) begin
                    res = temp_res;
                    res[N-1] = 1'b0;
                end else begin
                    res = temp_res;
                    res[N-1] = 1'b1;
                end
            end else begin

                temp_res = (-a_signed) + b_signed;
                if (-a_signed > b_signed) begin
                    res = temp_res;
                    res[N-1] = 1'b0;
                end else begin
                    res = temp_res;
                    res[N-1] = 1'b1;
                end
            end


            if (res == 0)
                res[N-1] = 1'b0;
        end
    end

    assign c = res;

