module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] round_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)

                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 3'b001;
                end


                3'b001: begin
                    if ((a_exponent == 8'hFF && a_mantissa != 0) || 
                        (b_exponent == 8'hFF && b_mantissa != 0)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                    end else if ((a_exponent == 8'hFF && b_exponent == 8'hFF) && 
                               (a_mantissa == 0 || b_mantissa == 0)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 127;
                        counter <= 3'b010;
                    end
                end


                3'b010: begin
                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    if (product[47]) begin
                        z_mantissa <= product[47:25];
                        guard_bit <= product[24];
                        round_bit <= product[23];
                        sticky <= |product[22:0];
                    end else if (product[46]) begin
                        z_mantissa <= product[46:24];
                        z_exponent <= z_exponent + 1;
                        guard_bit <= product[24];
                        round_bit <= product[23];
                        sticky <= |product[22:0];
                    end else begin
                        z_mantissa <= product[45:23];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= 3'b011;
                end


                3'b011: begin
                    round_mantissa = z_mantissa;
                    if (guard_bit && (round_bit || sticky)) begin
                        round_mantissa = z_mantissa + 1;
                        if (round_mantissa[22]) begin
                            round_mantissa = {1'b0, round_mantissa[22:1]};
                            z_exponent = z_exponent + 1;
                        end
                    end
                    counter <= 3'b100;
                end


                3'b100: begin
                    if (z_exponent > 254) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if (z_exponent < 0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], round_mantissa};
                    end
                    counter <= 3'b000;
                end
            endcase
        end
    end
endmodule

