module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 4;
            for (integer i = 0;
 i < 4;
 i = i + 1) begin
                stack_mem[i] <= 4'b0;
            end
        end else begin
            if (~FULL && !RW) begin 
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end else if (~EMPTY && RW) begin 
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end

endmodule

