reg [3:0] data;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        cnt <= 2'b00;
    else
        cnt <= (cnt == 2'b11) ? 2'b00 : cnt + 1;
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        data <= 4'b0;
    else
        data <= (cnt == 2'b11) ? d : {data[2:0], data[3]};
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        valid_out <= 1'b0;
    else
        valid_out <= (cnt == 2'b11);
end


always @(posedge clk) begin
    if (valid_out)
        dout <= data[3];
end

endmodule

