module traffic_light(
    input  wire        rst_n,
    input  wire        clk,
    input  wire        pass_request,
    output reg  [7:0]  clock,
    output reg         red,
    output reg         yellow,
    output reg         green
);
    parameter idle     = 2'b00;
    parameter s1_red   = 2'b01;
    parameter s2_yellow= 2'b10;
    parameter s3_green = 2'b11;

    reg  [1:0]  state, next_state;
    reg  [7:0]  cnt;
    reg         p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case(state)
                idle:    state <= s1_red;
                s1_red:  state <= (cnt == 0) ? s3_green : s1_red;
                s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= 10;
            end else if (!p_green && p_green) begin
                cnt <= 60;
            end else if (!p_yellow && p_yellow) begin
                cnt <= 5;
            end else if (!p_red && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red     <= 0;
            yellow  <= 0;
            green   <= 0;
            p_red   <= 0;
            p_yellow<= 0;
            p_green <= 0;
        end else begin
            p_red   <= red;
            p_yellow<= yellow;
            p_green <= green;

            case(state)
                idle: begin
                    red    <= 0;
                    yellow <= 0;
                    green  <= 0;
                end
                s1_red: begin
                    red    <= 1;
                    yellow <= 0;
                    green  <= 0;
                end
                s2_yellow: begin
                    yellow <= 1;
                    green  <= 0;
                    red    <= 0;
                end
                s3_green: begin
                    green  <= 1;
                    red    <= 0;
                    yellow <= 0;
                end
                default: begin
                    red    <= 0;
                    yellow <= 0;
                    green  <= 0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

