module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg dividend_sign;
    reg divisor_sign;
    reg [8:0] NEG_DIVISOR;

    reg [8:0] temp_remainder;
    reg quotient_bit;
    reg [7:0] quotient;
    reg [7:0] remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 16'b0;
            SR <= 17'b0;
            cnt <= 4'b0;
            start_cnt <= 0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            NEG_DIVISOR <= 9'b0;
            quotient <= 8'b0;
            remainder <= 8'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    abs_dividend <= (dividend[7]) ? (-dividend) : dividend;
                    abs_divisor <= (divisor[7]) ? (-divisor) : divisor;
                end else begin
                    dividend_sign <= 0;
                    divisor_sign <= 0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end

                SR <= {abs_dividend, 8'b0} << 1;
                NEG_DIVISOR <= -{1'b0, abs_divisor};

                cnt <= 4'b0001;
                start_cnt <= 1;
            end else begin
                if (start_cnt) begin
                    if (cnt == 8) begin

                        start_cnt <= 0;

                        if (sign) begin
                            quotient <= (dividend_sign ^ divisor_sign) ? (-SR[7:0]) : SR[7:0];
                            remainder <= (dividend_sign) ? (-SR[16:8][7:0]) : SR[16:8][7:0];
                        end else begin
                            quotient <= SR[7:0];
                            remainder <= SR[16:8][7:0];
                        end
                        res_valid <= 1;
                        result <= {remainder, quotient};
                    end else begin

                        temp_remainder = SR[16:8] - NEG_DIVISOR;
                        quotient_bit = (temp_remainder[8]) ? 1'b0 : 1'b1;
                        if (temp_remainder[8]) begin
                            SR[16:8] <= SR[16:8];
                        end else begin
                            SR[16:8] <= temp_remainder[7:0];
                        end
                        SR[7:0] <= {SR[6:0], quotient_bit};
                        cnt <= cnt + 1;
                    end
                end else if (res_valid) begin
                    res_valid <= 0;
                end
            end
        end
    end
endmodule

