module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;

    reg [15:0] a_reg, b_reg;

    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end

    always @(A, B) begin
        reg [15:0] rem;
        reg [15:0] quo;
        integer i;

        rem = 16'b0;
        quo = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((a_reg >> i) & 1);
            if (rem >= b_reg) begin
                quo[i] = 1;
                rem = rem - b_reg;
            end
        end

        result = quo;
        odd = rem;
    end
endmodule

