            if (i == 5'd16)
                done_r <= 1'b1;
            else if (i == 5'd17)
                done_r <= 1'b0;
            else
                done_r <= done_r;


            if (start && i == 5'd0) begin
                areg <= ain;
                breg <= bin;
            end


            if (start && i > 5'd0 && i < 5'd17) begin
                if (areg[i-1])
                    yout_r <= yout_r + (breg << (i-1));
            end


            yout <= yout_r;
            done <= done_r;
