    if (!rst_n) begin
        sum_reg <= 10'b0;
        count <= 2'b00;
        data_out <= 10'b0;
        valid_out <= 1'b0;
    end else begin
        valid_out <= 1'b0;

        if (valid_in) begin
            if (count == 2'b11) begin 
                data_out <= sum_reg + data_in;
                valid_out <= 1'b1;
                sum_reg <= 10'b0;
                count <= 2'b00;
            end else begin
                sum_reg <= sum_reg + data_in;
                count <= count + 1;
            end
        end
    end
end

