module fixed_point_adder #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);

    wire [N-1:0] a_magnitude = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_magnitude = b_sign ? (~b + 1) : b;

    always @* begin
        if (same_sign) begin
            res = a_magnitude + b_magnitude;
            res[N-1] = a_sign;
        end else begin
            if (a_magnitude > b_magnitude) begin
                res = a_magnitude - b_magnitude;
                res[N-1] = 0;
            end else if (b_magnitude > a_magnitude) begin
                res = b_magnitude - a_magnitude;
                res[N-1] = 1;
            end else begin
                res = 0;
                res[N-1] = 0;
            end
        end
    end

    always @* begin
        c = res;
    end

endmodule

