module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    always @* begin
        reg sign_a, sign_b;
        reg [N-1:0] res_temp;
        reg sign_res;
        reg [N-1:0] absolute_a, absolute_b;

        sign_a = a[N-1];
        sign_b = b[N-1];

        if (sign_a == sign_b) begin

            res_temp = a - b;
            sign_res = sign_a;
        end else begin

            if (sign_a == 0 && sign_b == 1) begin

                absolute_a = a;
                absolute_b = -b;
            end else begin

                absolute_a = -a;
                absolute_b = b;
            end

            if (absolute_a > absolute_b) begin
                res_temp = absolute_a - absolute_b;
                sign_res = 0;
            end else begin
                res_temp = absolute_b - absolute_a;
                sign_res = 1;
            end
        end


        if (res_temp == 0)
            sign_res = 0;

        res = {sign_res, res_temp[N-2:0]};
    end

    assign c = res;
endmodule

