module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky_bit;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    z_sign <= a_sign ^ b_sign;


                    if (a_exponent == 8'hff && a_mantissa != 0) begin
                        z <= {z_sign, 8'hff, a_mantissa};
                    end else if (b_exponent == 8'hff && b_mantissa != 0) begin
                        z <= {z_sign, 8'hff, b_mantissa};
                    end else if (a_exponent == 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (b_exponent == 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (a_exponent == 8'h0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else if (b_exponent == 8'h0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b001: begin

                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    counter <= counter + 1;
                end
                3'b010: begin

                    reg [23:0] ma_rounded;
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end


                    if (product[47]) begin
                        ma_rounded = product[46:24];
                        guard_bit = product[23];
                        round_bit = product[22];
                        sticky_bit = |product[21:0];
                    end else begin
                        ma_rounded = product[47:25];
                        guard_bit = product[24];
                        round_bit = product[23];
                        sticky_bit = |product[22:0];
                    end


                    reg round_up;
                    round_up = (guard_bit && (round_bit || sticky_bit)) || 
                              (guard_bit && !round_bit && !sticky_bit && ma_rounded[0]);
                    ma_rounded = ma_rounded + round_up;


                    if (ma_rounded[23]) begin
                        ma_rounded = 23'b0;
                        z_exponent <= z_exponent + 1;
                    end


                    if (z_exponent > 8'hff) begin
                        z_exponent <= 8'hff;
                        ma_rounded <= 23'b0;
                    end else if (z_exponent < 8'h0) begin
                        z_exponent <= 8'h0;
                        ma_rounded <= 23'b0;
                    end


                    z <= {z_sign, z_exponent, ma_rounded};
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
