module asyn_fifo #(parameter WIDTH = 8, DEPTH = 16) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output reg rempty,
    output reg wfull,
    output reg [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;

    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [ADDR_WIDTH-1:0] waddr = waddr_bin;
    wire [ADDR_WIDTH-1:0] raddr = raddr_bin;
    reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
    wire [PTR_WIDTH-1:0] wptr = wptr_bin;
    wire [PTR_WIDTH-1:0] rptr = rptr_bin;
    reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;
    reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
    reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;


    wire wen, ren;
    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_bin <= 0;
        end else if (wen) begin
            waddr_bin <= waddr_bin + 1;
            wptr_bin <= wptr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_bin <= 0;
        end else if (ren) begin
            raddr_bin <= raddr_bin + 1;
            rptr_bin <= rptr_bin + 1;
        end
    end


    always @(*) begin
        wptr_gray = wptr_bin ^ (wptr_bin >> 1);
        rptr_gray = rptr_bin ^ (rptr_bin >> 1);
    end


    always @(posedge rclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end
    wire [PTR_WIDTH-1:0] wptr_gray_sync = wptr_gray_sync2;


    always @(posedge wclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end
    wire [PTR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync2;


    always @(*) begin
        rempty = (rptr_gray == wptr_gray_sync);
        wfull = (wptr_gray[ADDR_WIDTH-1] != wptr_gray_sync[ADDR_WIDTH-1]) &&
                (wptr_gray[ADDR_WIDTH-2] != wptr_gray_sync[ADDR_WIDTH-2]) &&
                (wptr_gray[ADDR_WIDTH-3:0] == wptr_gray_sync[ADDR_WIDTH-3:0]);
    end

endmodule

module dual_port_RAM #(parameter WIDTH = 8, DEPTH = 16) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
