module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;

    reg [2:0] next_SP;


    always @(posedge Clk) begin
        if (Rst) begin

            SP <= 4;
            EMPTY <= 1;
            FULL <= 0;
            dataOut <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end else if (EN) begin
            next_SP = SP;

            dataOut <= dataOut;


            if (!FULL && !EMPTY) begin
                if (!RW) begin 
                    stack_mem[SP-1] <= dataIn;
                    next_SP = SP - 1;
                end else begin 
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 0;
                    next_SP = SP + 1;
                end
            end

            SP <= next_SP;

            EMPTY <= (next_SP == 4);

            FULL <= (next_SP == 0);
        end
    end
endmodule

