module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


parameter State_0 = 2'b00,
          State_1 = 2'b01,
          State_2 = 2'b10;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= State_0;
        data_out <= 1'b0;
    end else begin
        case (state)
            State_0: begin
                if (data_in) begin
                    state <= State_1;
                    data_out <= 1'b0;
                end else begin
                    state <= State_0;
                    data_out <= 1'b0;
                end
            end
            State_1: begin
                if (~data_in) begin
                    state <= State_2;
                    data_out <= 1'b1;
                end else begin
                    state <= State_0;
                    data_out <= 1'b0;
                end
            end
            State_2: begin
                state <= State_0;
                data_out <= 1'b0;
            end
            default: begin
                state <= State_0;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

