module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero, negative,
    output reg carry, overflow,
    output reg flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;


reg [32:0] sum_add, sub_add;
wire [31:0] slt_res, sltu_res;


assign zero = (r == 32'b0);
assign negative = r[31];


always @(*) begin
    case (aluc)
        SLT: flag = slt_res[0];
        SLTU: flag = sltu_res[0];
        default: flag = 1'bz;
    endcase
end


assign slt_res  = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
assign sltu_res = (a < b) ? 32'd1 : 32'd0;


always @(*) begin
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: {carry, r} = {1'b0, a} + {1'b0, b};
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: {carry, r} = {1'b0, a} - {1'b0, b};
        AND:  {r, carry, overflow} = {a & b, 1'b0, 1'b0};
        OR:   {r, carry, overflow} = {a | b, 1'b0, 1'b0};
        XOR:  {r, carry, overflow} = {a ^ b, 1'b0, 1'b0};
        NOR:  {r, carry, overflow} = {~(a | b), 1'b0, 1'b0};
        SLT:  {r, carry, overflow} = {slt_res, 1'b0, 1'b0};
        SLTU: {r, carry, overflow} = {sltu_res, 1'b0, 1'b0};
        SLL:  {r, carry} = {a << b[4:0], 1'b0};
        SRL:  {r, carry} = {a >> b[4:0], 1'b0};
        SRA:  {r, carry} = { $signed(a) >>> b[4:0], 1'b0 };
        SLLV: {r, carry} = {b << a[4:0], 1'b0};
        SRLV: {r, carry} = {b >> a[4:0], 1'b0};
        SRAV: {r, carry} = { $signed(b) >>> a[4:0], 1'b0 };
        LUI:  {r, carry} = { {a[31:16], 16'b0}, 1'b0 };
        default: {r, carry, overflow} = {32'bz, 1'b0, 1'b0};
    endcase

    if (!(aluc inside {ADD, ADDU, SUB, SUBU})) overflow = 1'b0;
end

endmodule

