module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg sign_quotient, sign_remainder;
    reg [8:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            SR <= 0;
            NEG_DIVISOR <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            result <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end else if (opn_valid && !res_valid) begin

                reg [7:0] abs_dividend, abs_divisor;
                reg s_dividend, s_divisor;
                if (sign) begin
                    s_dividend = dividend[7];
                    s_divisor = divisor[7];
                    abs_dividend = s_dividend ? -dividend : dividend;
                    abs_divisor = s_divisor ? -divisor : divisor;
                    sign_quotient <= s_dividend ^ s_divisor;
                    sign_remainder <= s_dividend;
                end else begin
                    abs_dividend = dividend;
                    abs_divisor = divisor;
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                end
                dividend_reg <= abs_dividend;
                divisor_reg <= abs_divisor;
                SR <= {abs_dividend, 1'b0};
                NEG_DIVISOR <= -abs_divisor;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && !res_valid) begin
                if (cnt == 8) begin
                    start_cnt <= 0;
                    cnt <= 0;

                    if (sign_quotient)
                        result[7:0] <= -result[7:0];
                    if (sign_remainder)
                        result[15:8] <= -result[15:8];
                    res_valid <= 1;
                end else begin
                    reg [8:0] shifted_sr = SR << 1;
                    reg [8:0] sub_result = shifted_sr - NEG_DIVISOR;
                    reg carry_out = (shifted_sr < NEG_DIVISOR);
                    if (carry_out) begin
                        SR <= shifted_sr;
                    end else begin
                        SR <= sub_result;
                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end

    always @(*) begin
        if (cnt < 8)
            result[15:8] <= SR[8:1];
        else
            result[15:8] <= 0;
        if (cnt < 8)
            result[7:0] <= {7'b0, SR[0]};
        else
            result[7:0] <= 0;
    end

endmodule

