    assign P = &P_i;


    always @(*) begin
        products[0] = 1'b1;

        for (i=1;
 i<16;
 i=i+1) begin
            products[i] = products[i-1] & P_i[i];
        end


        G_total = 0;
        for (i=0;
 i<16;
 i=i+1) begin
            terms[i] = G_i[i+1] & products[i];
            G_total = G_total + terms[i];
        end
    end


    reg [16:0] C;
    assign C[0] = C_in;
    always @(*) begin
        for (i=1;
 i<=16;
 i=i+1) begin
            C[i] = G_i[i] | (P_i[i] & C[i-1]);
        end
    end


    assign S = (P_i ^ B) & {16{C[16:1]}};


    assign G = G_total;

endmodule

