module fixed_point_adder #(parameter Q = 2, parameter N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N-1:0] abs_diff_a_b = abs_a - abs_b;
    wire [N-1:0] abs_diff_b_a = abs_b - abs_a;

    always @* begin
        if (sign_a == sign_b) begin
            res = a + b;
            res[N-1] = sign_a;

        end else begin
            if (abs_a > abs_b) begin
                res = {sign_a, abs_diff_a_b};
            end else if (abs_b > abs_a) begin
                res = {sign_b, abs_diff_b_a};
            end else begin
                res = {1'b0, {N-1{1'b0}}};

            end
        end
    end

    assign c = res;

endmodule

