module fixed_point_subtractor #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;
reg [N-1:0] abs_a, abs_b;
reg [N-1:0] sum_abs;
reg result_sign;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];


    if (sign_a == sign_b) begin
        res = a - b;
        res[N-1] = sign_a;
    end else begin

        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;
        sum_abs = abs_a + abs_b;

        result_sign = ($signed(a) > $signed(b)) ? 1'b0 : 1'b1;

        res = {result_sign, sum_abs[N-2:0]};
    end


    if (res == 0)
        res[N-1] = 1'b0;

    c = res;
end

endmodule

