module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            z_sign <= 0;
            z_exponent <= 0;
            z_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if ((a_exponent == 8'hff) && |a_mantissa) begin

                        z <= {a_sign ^ b_sign, 8'hff, a_mantissa};
                    end else if ((b_exponent == 8'hff) && |b_mantissa) begin

                        z <= {a_sign ^ b_sign, 8'hff, b_mantissa};
                    end else if (a_exponent == 8'hff) begin

                        if (b_exponent == 8'h00) begin
                            if (b_mantissa != 0)
                                z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                            else
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else if (b_exponent == 8'h00) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                    end else if (b_exponent == 8'hff) begin

                        if (a_exponent == 8'h00) begin
                            if (a_mantissa != 0)
                                z <= {1'b0, 8'hff, 23'h1};

                            else
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else if (a_exponent == 8'h00) begin
                            z <= {1'b0, 8'hff, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                    end else if (a_exponent == 8'h00) begin

                        if (b_exponent == 8'h00)
                            z <= {a_sign ^ b_sign, 31'h0};

                        else
                            z <= {a_sign ^ b_sign, 31'h0};

                    end else if (b_exponent == 8'h00) begin

                        z <= {a_sign ^ b_sign, 31'h0};

                    end else begin
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 9'd254;
                        counter <= counter + 1;
                    end
                    if (z != 0) begin
                        counter <= 3'b0;

                    end
                end
                3'b010: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                3'b011: begin

                    z_mantissa <= product[46:24];
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        if (z_mantissa == 23'h7fffff) begin
                            z_mantissa <= 23'h0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (z_exponent >= 9'd255) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent <= 9'd0) begin
                        z <= {z_sign, 31'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end
