module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);


localparam IDLE = 3'b000,
           S1 = 3'b001,
           S2 = 3'b010,
           S3 = 3'b011,
           S4 = 3'b100;

reg [2:0] current_state, next_state;


always @(posedge clk or negedge reset_n) begin
    if (!reset_n)
        current_state <= IDLE;
    else
        current_state <= next_state;
end


always @(*) begin
    case (current_state)
        IDLE: next_state = data_in ? S1 : IDLE;
        S1:   next_state = (data_in == 0) ? S2 : S1;
        S2:   next_state = (data_in == 0) ? S3 : IDLE;
        S3:   next_state = (data_in == 1) ? S4 : IDLE;
        S4:   next_state = (data_in == 1) ? S1 : IDLE;
        default: next_state = IDLE;
    endcase
end


assign sequence_detected = (current_state == S4);

endmodule

