module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] saved_dividend, saved_divisor;
    reg saved_q_sign, saved_r_sign;
    reg [7:0] abs_dividend, abs_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg sign_reg;
    reg [8:0] neg_divisor;
    reg [8:0] subtract_result;
    reg carry_out;
    reg [7:0] quotient_adj, remainder_adj;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 16'b0;
            cnt <= 0;
            start_cnt <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            saved_q_sign <= 0;
            saved_r_sign <= 0;
            sign_reg <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                sign_reg <= sign;
                saved_q_sign <= 0;
                saved_r_sign <= 0;
                if (sign) begin
                    saved_dividend <= dividend[7] ? -dividend : dividend;
                    saved_divisor <= divisor[7] ? -divisor : divisor;
                    saved_q_sign <= (dividend[7] ^ divisor[7]);
                    saved_r_sign <= dividend[7];
                end else begin
                    saved_dividend <= dividend;
                    saved_divisor <= divisor;
                end
                abs_dividend = saved_dividend;
                abs_divisor = saved_divisor;
                neg_divisor <= -abs_divisor;
                SR <= {abs_dividend, 8'b0} << 1;
                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end

            if (start_cnt) begin
                if (cnt == 8) begin
                    start_cnt <= 0;
                    cnt <= 0;
                    res_valid <= 1;
                end else begin
                    subtract_result <= SR[15:8] - neg_divisor[7:0];
                    carry_out <= ~subtract_result[8];
                    if (carry_out) begin
                        SR[15:8] <= subtract_result[7:0];
                        SR[7:0] <= {SR[6:0], 1'b1};
                    end else begin
                        SR[7:0] <= {SR[7:1], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end

            if (res_valid) begin
                if (sign_reg) begin
                    quotient_adj <= saved_q_sign ? -SR[7:0] : SR[7:0];
                    remainder_adj <= saved_r_sign ? -SR[15:8][7:0] : SR[15:8][7:0];
                end else begin
                    quotient_adj <= SR[7:0];
                    remainder_adj <= SR[15:8][7:0];
                end
                result <= {remainder_adj, quotient_adj};
            end
        end
    end
endmodule

