    output reg [15:0] product;

    always @* begin
        reg [15:0] A_shifted;
        reg [7:0] B_shifted;
        integer i;

        A_shifted = {8'b0, A};
        B_shifted = B;
        product = 16'b0;

        for (i = 0;
 i < 8;
 i = i + 1) begin
            if (B_shifted[0]) begin
                product = product + A_shifted;
            end
            A_shifted = A_shifted << 1;
            B_shifted = B_shifted >> 1;
        end
    end
