module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output reg done
);
    reg [4:0] i;

    reg [15:0] areg;

    reg [15:0] breg;

    reg [31:0] yout_r;

    assign yout = yout_r;

    always @(posedge clk or negedge rst_n) begin
        reg [4:0] next_i;
        if (!rst_n) begin
            i <= 0;
            done <= 0;
            areg <= 0;
            breg <= 0;
            yout_r <= 0;
        end else begin

            if (start) begin
                next_i = (i < 17) ? (i + 1) : i;
            end else begin
                next_i = 0;
            end


            if (next_i == 16)
                done <= 1;
            else if (next_i == 17)
                done <= 0;


            i <= next_i;


            if (start) begin
                if (next_i == 0) begin
                    areg <= ain;
                    breg <= bin;
                end else if (next_i > 0 && next_i < 17) begin
                    if (areg[next_i - 1])
                        yout_r <= yout_r + (breg << (next_i - 1));
                end
            end else begin
                areg <= 0;
                breg <= 0;
                yout_r <= 0;
            end
        end
    end
