module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);
    reg [9:0] sum_reg;
    reg [1:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            sum_reg <= 10'b0;
            counter <= 2'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            if (valid_in) begin
                sum_reg <= sum_reg + data_in;
                counter <= counter + 1;
            end

            if (counter == 2'b11 && valid_in) begin
                valid_out <= 1'b1;
                data_out <= sum_reg + data_in;
            end else begin
                valid_out <= 1'b0;
                data_out <= 10'b0;
            end
        end
    end
endmodule

