module fixed_point_adder #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire signed [N-1:0] a_signed = a;
    wire signed [N-1:0] b_signed = b;

    always @* begin
        if (sign_a == sign_b) begin

            reg [N-1:0] abs_a, abs_b;
            abs_a = sign_a ? (-a_signed) : a_signed;
            abs_b = sign_b ? (-b_signed) : b_signed;
            res = (a_signed + b_signed);
        end else begin

            reg [N-1:0] abs_a, abs_b;
            abs_a = sign_a ? (-a_signed) : a_signed;
            abs_b = sign_b ? (-b_signed) : b_signed;
            if (abs_a > abs_b) begin
                res = (a_signed - b_signed);
            end else begin
                res = (b_signed - a_signed);
            end
        end
        c = res;
    end
endmodule

