module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
reg sign_a, sign_b;
reg [N-1:0] res;
reg sign_res;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    res = 0;
    sign_res = 0;


    if (sign_a == sign_b) begin
        res = a - b;
        sign_res = sign_a;
    end else begin

        if (sign_a == 0 && sign_b == 1) begin

            res = a + (-b);
            if (a > (-b)) begin
                sign_res = 0;
            end else begin
                sign_res = 1;
            end
        end else begin

            res = (-a) + b;
            if ((-a) > b) begin
                sign_res = 0;
            end else begin
                sign_res = 1;
            end
        end
    end


    if (res == 0) begin
        sign_res = 0;
    end


    c = {sign_res, res[Q-1:0]};
end

endmodule

