module asyn_fifo #(parameter DEPTH = 16, WIDTH = 8) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output reg [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);

    reg [ADDR_WIDTH:0] waddr_bin, raddr_bin;
    reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;
    reg [ADDR_WIDTH:0] rptr_gray_sync1, rptr_gray_sync2;
    reg [ADDR_WIDTH:0] wptr_gray_sync1, wptr_gray_sync2;
    wire [ADDR_WIDTH:0] raddr_sync_w, waddr_sync_r;

    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
        .wclk(wclk),
        .wenc(winc & ~wfull),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc & ~rempty),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) waddr_bin <= 0;
        else if (winc && ~wfull) waddr_bin <= waddr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) raddr_bin <= 0;
        else if (rinc && ~rempty) raddr_bin <= raddr_bin + 1;
    end


    always @* begin
        wptr_gray = waddr_bin ^ (waddr_bin >> 1);
        rptr_gray = raddr_bin ^ (raddr_bin >> 1);
    end


    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    reg [ADDR_WIDTH:0] raddr_sync_w;
    always @* begin
        raddr_sync_w = 0;
        raddr_sync_w[ADDR_WIDTH] = rptr_gray_sync2[ADDR_WIDTH];
        for (integer i = ADDR_WIDTH-1;
 i >=0;
 i = i -1)
            raddr_sync_w[i] = rptr_gray_sync2[i] ^ raddr_sync_w[i+1];
    end


    always @* begin
        wfull = (waddr_bin[ADDR_WIDTH] != raddr_sync_w[ADDR_WIDTH]) &&
                (waddr_bin[ADDR_WIDTH-1:0] == raddr_sync_w[ADDR_WIDTH-1:0]);
    end


    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    reg [ADDR_WIDTH:0] waddr_sync_r;
    always @* begin
        waddr_sync_r = 0;
        waddr_sync_r[ADDR_WIDTH] = wptr_gray_sync2[ADDR_WIDTH];
        for (integer i = ADDR_WIDTH-1;
 i >=0;
 i = i -1)
            waddr_sync_r[i] = wptr_gray_sync2[i] ^ waddr_sync_r[i+1];
    end


    always @* begin
        rempty = (raddr_bin == waddr_sync_r);
    end
endmodule

module dual_port_RAM #(parameter DEPTH=16, WIDTH=8) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
