module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg state;
    localparam IDLE = 1'b0;
    localparam GOT_HIGH = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= GOT_HIGH;
                        data_out <= 0;
                    end else begin
                        data_out <= 0;
                    end
                end
                GOT_HIGH: begin
                    if (!data_in) begin
                        state <= IDLE;
                        data_out <= 1;
                    end else begin
                        state <= GOT_HIGH;
                        data_out <= 0;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

