                    s3_green = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                end
                s1_red: begin
                    if (cnt == 3)
                        state <= s3_green;
                end
                s3_green: begin
                    if (cnt == 3)
                        state <= s2_yellow;
                end
                s2_yellow: begin
                    if (cnt == 3)
                        state <= s1_red;
                end
                default: state <= idle;
            endcase
            case (state)
                idle:    {p_red, p_yellow, p_green} <= 3'b000;
                s1_red:  {p_red, p_yellow, p_green} <= 3'b100;
                s3_green: {p_red, p_yellow, p_green} <= 3'b001;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                default: {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 10;
        else begin
            if (pass_request && p_green)
                cnt <= 10;
            else if (!p_green && p_green_prev)
                cnt <= 60;
            else if (!p_yellow && p_yellow_prev)
                cnt <= 5;
            else if (!p_red && p_red_prev)
                cnt <= 10;
            else
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red_prev, p_yellow_prev, p_green_prev} <= 3'b000;
        end else begin
            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b000;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;
