module width_8to16 (
    input           clk,
    input           rst_n,
    input           valid_in,
    input  [7:0]    data_in,
    output reg      valid_out,
    output reg [15:0] data_out
);
    reg [7:0] data_lock;
    reg state;
    reg valid_next;
    reg [15:0] data_out_reg;

    localparam IDLE = 1'b0;
    localparam WAIT_SECOND = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            data_lock <= 8'b0;
            state <= IDLE;
            valid_out <= 1'b0;
            data_out <= 16'b0;
            valid_next <= 1'b0;
            data_out_reg <= 16'b0;
        end else begin
            valid_out <= valid_next;
            data_out <= data_out_reg;
            valid_next <= 1'b0;

            case (state)
                IDLE: begin
                    if (valid_in) begin
                        data_lock <= data_in;
                        state <= WAIT_SECOND;
                    end
                end
                WAIT_SECOND: begin
                    if (valid_in) begin
                        data_out_reg <= {data_lock, data_in};
                        valid_next <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

