module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] divd_reg, divs_reg;
    reg [7:0] abs_divd, abs_divs;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIV;
    wire [8:0] remainder;
    wire [7:0] divisor_abs;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            divd_reg <= 0;
            divs_reg <= 0;
            abs_divd <= 0;
            abs_divs <= 0;
            NEG_DIV <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                divd_reg <= dividend;
                divs_reg <= divisor;

                abs_divd <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                abs_divs <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;

                SR <= {abs_divd, 1'b0};
                cnt <= 0;
                start_cnt <= 1;
                NEG_DIV <= ~abs_divs + 1;

            end else if (start_cnt) begin
                if (cnt < 4'd8) begin

                    remainder = SR[16:8] - divisor_abs;
                    if (remainder[8] == 0) begin 
                        SR <= {remainder[7:0], (SR[7:0] << 1) | 1'b1};
                    end else begin
                        SR <= {SR[16:8], (SR[7:0] << 1)};
                    end
                    cnt <= cnt + 1;
                end else begin

                    start_cnt <= 0;
                    res_valid <= 1;
                    result <= {SR[16:9], SR[8:1]};

                end
            end else if (res_valid) begin

                res_valid <= 0;
            end
        end
    end
endmodule

