module adder_bcd(A, B, Cin, Sum, Cout);
  input [3:0] A, B;
  input Cin;
  output [3:0] Sum;
  output Cout;

  wire [4:0] temp_sum;
  wire do_correction;

  assign temp_sum = {1'b0, A} + {1'b0, B} + Cin;
  assign do_correction = temp_sum[4] | (temp_sum[3:0] > 4'd9);
  assign Sum = do_correction ? (temp_sum[3:0] + 4'd6) : temp_sum[3:0];
  assign Cout = do_correction;

endmodule

