module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg a_sign, b_sign;
reg [N-1:0] a_abs, b_abs;
reg [N-1:0] abs_diff;
reg res_sign;

always @(*) begin
    a_sign = a[N-1];
    b_sign = b[N-1];


    if ($signed(a) < 0)
        a_abs = -$signed(a);
    else
        a_abs = a;

    if ($signed(b) < 0)
        b_abs = -$signed(b);
    else
        b_abs = b;


    if (a_sign == b_sign) begin

        res = $signed(a) + $signed(b);
        res_sign = a_sign;
    end else begin

        if (a_abs > b_abs) begin
            abs_diff = a_abs - b_abs;
            res_sign = a_sign;
        end else if (b_abs > a_abs) begin
            abs_diff = b_abs - a_abs;
            res_sign = b_sign;
        end else begin
            abs_diff = 0;
            res_sign = 0;
        end
        res = {res_sign, abs_diff[N-2:0]};
    end


    c = res;
end

endmodule

