module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c = 0
);
    reg sign_a, sign_b;
    reg [N-1:0] res;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];


        if (sign_a != sign_b) begin
            reg [N-1:0] a_mag, b_mag;
            a_mag = sign_a ? (~a + 1) : a;
            b_mag = sign_b ? (~b + 1) : b;
            if (a_mag > b_mag) begin
                res = a_mag - b_mag;
                res[N-1] = sign_a;
            end else if (b_mag > a_mag) begin
                res = b_mag - a_mag;
                res[N-1] = sign_b;
            end else begin
                res = 0;
            end
        end else begin

            res = a - b;

            res[N-1] = res[N-1];

        end


        if (res == 0)
            res[N-1] = 0;
    end

    assign c = res;
endmodule

