module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [22:0] mantissa_round;
    reg [8:0] exponent_tmp;
    reg overflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    if (a[30:23] == 0) begin
                        a_mantissa <= {1'b0, a[22:0]};
                        a_exponent <= 9'd1 - 9'd127;
                    end else begin
                        a_mantissa <= {1'b1, a[22:0]};
                        a_exponent <= {1'b0, a[30:23]} - 9'd127;
                    end
                    if (b[30:23] == 0) begin
                        b_mantissa <= {1'b0, b[22:0]};
                        b_exponent <= 9'd1 - 9'd127;
                    end else begin
                        b_mantissa <= {1'b1, b[22:0]};
                        b_exponent <= {1'b0, b[30:23]} - 9'd127;
                    end

                    if (a[30:23] == 8'hFF || b[30:23] == 8'hFF) begin
                        z_sign <= a_sign ^ b_sign;
                        if (a[30:23] == 8'hFF) begin
                            z <= {a_sign ^ b_sign, 8'hFF, a[22:0] != 0};
                        end else if (b[30:23] == 8'hFF) begin
                            z <= {a_sign ^ b_sign, 8'hFF, b[22:0] != 0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'd0};
                        end
                        counter <= 1;
                    end else if (a == 0 || b == 0) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                        counter <= 1;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        exponent_tmp <= a_exponent + b_exponent;
                        counter <= 1;
                    end
                end
                1: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        exponent_tmp <= exponent_tmp + 1;
                    end

                    guard <= product[0];
                    round <= product[1];
                    sticky <= |product[47:2];
                    counter <= 2;
                end
                2: begin

                    mantissa_round <= product[46:24];
                    if (guard && (round || sticky)) begin
                        mantissa_round <= mantissa_round + 1;
                        if (mantissa_round == 23'h7FFFFF) begin 
                            product <= product >> 1;
                            exponent_tmp <= exponent_tmp + 1;
                        end
                    end

                    if (exponent_tmp >= 9'd255) begin
                        z <= {z_sign, 8'hFF, 23'd0};
                    end else if (exponent_tmp <= 0) begin
                        z <= {z_sign, 31'd0};
                    end else begin
                        z <= {z_sign, exponent_tmp[7:0], mantissa_round};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end
endmodule

