module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg state;
    localparam state0 = 1'b0;
    localparam state1 = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= state0;
            data_out <= 1'b0;
        end else begin
            case (state)
                state0: begin
                    if (data_in) begin
                        state <= state1;
                    end
                    data_out <= 1'b0;
                end
                state1: begin
                    if (!data_in) begin
                        state <= state0;
                        data_out <= 1'b1;
                    end else begin
                        data_out <= 1'b0;
                    end
                end
                default: begin
                    state <= state0;
                    data_out <= 1'b0;
                end
            endcase
        end
    end
endmodule

