module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: state <= (cnt == 3) ? s3_green : s1_red;
            s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
            s3_green: state <= (cnt == 3) ? s2_yellow : s3_green;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && green) begin
            cnt <= 8'd10;
        end else begin
            case (1'b1)
                (green && !p_green): cnt <= 8'd60;
                (yellow && !p_yellow): cnt <= 8'd5;
                (red && !p_red): cnt <= 8'd10;
                default: cnt <= cnt - 8'd1;
            endcase
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 3'b000;
    end else begin
        {p_red, p_yellow, p_green} <= {red, yellow, green};
    end
end


always @(*) begin
    case (state)
        idle:     {red, yellow, green} = 3'b000;
        s1_red:   {red, yellow, green} = 3'b100;
        s2_yellow:{red, yellow, green} = 3'b010;
        s3_green: {red, yellow, green} = 3'b001;
        default:  {red, yellow, green} = 3'b000;
    endcase
end

assign clock = cnt;

endmodule

