module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [8:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend, abs_divisor;
    reg sign_dividend, sign_divisor;
    reg [7:0] quotient, remainder;
    wire [8:0] temp_sub;
    wire carry_out;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                res_valid <= 0;
                start_cnt <= 1;
                cnt <= 4'd1;
                sign_dividend <= sign ? dividend[7] : 0;
                sign_divisor <= sign ? divisor[7] : 0;
                if (sign) begin
                    abs_dividend <= (dividend[7]) ? -dividend : dividend;
                    abs_divisor <= (divisor[7]) ? -divisor : divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end
                SR <= {abs_dividend, 1'b0} << 1;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin
                    start_cnt <= 0;
                    cnt <= 0;
                    if (sign) begin
                        if (sign_dividend ^ sign_divisor)
                            quotient <= -remainder;
                        if (sign_dividend)
                            remainder <= -remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin
                    temp_sub = SR - (-abs_divisor);
                    carry_out = ~temp_sub[8];
                    if (carry_out) begin
                        SR <= (temp_sub << 1) | 1;
                        quotient <= (quotient << 1) | 1;
                    end else begin
                        SR <= (SR << 1);
                        quotient <= quotient << 1;
                    end
                    remainder <= (carry_out) ? temp_sub[7:0] : SR[7:0];
                    cnt <= cnt + 1;
                end
            end
        end
    end
endmodule

