module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result = 0;
    output reg [15:0] odd = 0;
    reg [15:0] a_reg, b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(a_reg, b_reg) begin
        reg [15:0] dividend = a_reg;
        reg [7:0] divisor = b_reg;
        reg [15:0] quotient = 0;
        reg [15:0] remainder = 0;
        integer i;


        remainder[15:8] = dividend[15:8];
        remainder[7:0] = 0;


        for (i = 0;
 i < 16;
 i = i + 1) begin

            remainder = {remainder[7:0], dividend[15 - i]};


            if (remainder[15:8] >= divisor) begin
                quotient[i] = 1;
                remainder[15:8] = remainder[15:8] - divisor;
            end else begin
                quotient[i] = 0;
            end


            remainder = {remainder[7:0], 1'b0};
        end

        result = quotient;
        odd = remainder;
    end
endmodule

