module cla_16bit (A, B, C_in, S, G, P);
    input [16:1] A, B;
    input C_in;
    output [16:1] S;
    output G, P;

    wire [16:1] g, p;
    wire [16:0] c;


    genvar i;
    generate
        for (i=1;
 i<=16;
 i=i+1) begin : gp_gen
            assign g[i] = A[i] & B[i];
            assign p[i] = A[i] ^ B[i];
        end
    endgenerate


    generate
        for (i=1;
 i<=16;
 i=i+1) begin : carry_gen
            wire [i-1:0] G_terms;
            wire P_terms;
            genvar j;
            for (j=0;
 j <= i-1;
 j=j+1) begin : term_gen
                if (j == i-1) begin
                    assign G_terms[j] = g[j];
                end else begin
                    assign G_terms[j] = g[j] & (& p[j+1:i-1]);
                end
            end
            assign P_terms = & p[1:i-1];
            assign c[i] = (|G_terms) | (P_terms & C_in);
        end
    endgenerate


    generate
        for (i=1;
 i<=16;
 i=i+1) begin : sum_gen
            assign S[i] = p[i] ^ c[i];
        end
    endgenerate


    reg G_reg, P_reg;
    integer k;
    always @(*) begin
        G_reg = 1'b0;
        P_reg = 1'b1;
        for (k=1;
 k <= 16;
 k=k+1) begin
            G_reg = G_reg | (g[k] & (& p[1:k]));
            P_reg = P_reg & p[k];
        end
    end

    assign G = G_reg;
    assign P = P_reg;

endmodule

