module fixed_point_adder #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire [N-2:0] abs_a, abs_b;
    wire [N-1:0] abs_a_twos, abs_b_twos;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];


    assign abs_a_twos = sign_a ? (~a + 1) : a;
    assign abs_b_twos = sign_b ? (~b + 1) : b;


    assign abs_a = abs_a_twos[N-2:0];
    assign abs_b = abs_b_twos[N-2:0];

    always @* begin
        if (sign_a == sign_b) begin

            res = abs_a + abs_b;
            res[N-1] = sign_a;
        end else begin

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = sign_a;
            end else begin
                res = abs_b - abs_a;
                res[N-1] = sign_b;
            end
        end
        c = res;
    end

endmodule

