module fixed_point_subtractor #(parameter Q, N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    reg [N-1:0] abs_a;
    reg [N-1:0] abs_b;
    reg [N-1:0] sum;
    reg sign_res;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = a - b;
            sign_res = sign_a;
        end else begin

            if (sign_a) begin
                abs_a = ~a + 1;

                abs_b = b;
            end else begin
                abs_a = a;
                abs_b = ~b + 1;

            end
            sum = abs_a + abs_b;


            sign_res = (abs_a > abs_b) ? 1'b0 : 1'b1;


            res = (sign_res) ? ~sum + 1 : sum;
        end


        if (res == {N{1'b0}}) begin
            sign_res = 1'b0;
            res = {N{1'b0}};
        end else begin
            res[N-1] = sign_res;

        end
    end

    assign c = res;
endmodule

