module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;

reg [47:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        z_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        z_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
    end else begin
        case (counter)

            3'b000: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {1'b1, a[22:0]};

                b_mantissa <= {1'b1, b[22:0]};
                counter <= counter + 1;
            end

            3'b001: begin

                if ((a_exponent == 8'hff && |a_mantissa) || 
                    (b_exponent == 8'hff && |b_mantissa)) begin
                    z <= {1'b0, 8'hff, 23'h1};
                    counter <= 3'b111;
                end 

                else if ((a_exponent == 8'hff && a_mantissa == 0) || 
                         (b_exponent == 8'hff && b_mantissa == 0)) begin
                    if ((a_exponent != 8'hff) && (b_exponent != 8'hff)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end
                    counter <= 3'b111;
                end 

                else if (a == 0 || b == 0) begin
                    z <= {a_sign ^ b_sign, 31'h0};
                    counter <= 3'b111;
                end 

                else begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end
            end

            3'b010: begin
                if (product[47]) begin
                    product <= product >> 1;
                    z_exponent <= z_exponent + 1;
                end

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];
                counter <= counter + 1;
            end

            3'b011: begin

                if (guard_bit && (round_bit || sticky || product[23])) begin
                    product[22:0] <= product[22:0] + 1;
                    if (product[22:0] == 23'h7fffff) begin 
                        product[22:0] <= 23'h0;
                        z_exponent <= z_exponent + 1;
                    end
                end
                counter <= counter + 1;
            end

            3'b100: begin
                if (z_exponent >= 8'hff) begin
                    z <= {z_sign, 8'hff, 23'h0};

                end else if (z_exponent == 0 && product[22:0] != 0) begin

                    z <= {z_sign, 8'h0, product[22:0]};
                end else begin
                    z <= {z_sign, z_exponent[7:0], product[22:0]};
                end
                counter <= 3'b0;

            end
            default: begin
                z <= 32'b0;
                counter <= 3'b0;
            end
        endcase
