module sub_64bit(A, B, result, overflow);
    input signed [63:0] A, B;
    output signed [63:0] result;
    output overflow;

    assign result = A - B;

    wire A_pos = ~A[63];

    wire B_neg = B[63];

    wire result_neg = result[63];

    wire A_neg = A[63];

    wire B_pos = ~B[63];

    wire result_pos = ~result[63];




    assign overflow = (A_pos & B_neg & result_neg) | (A_neg & B_pos & result_pos);
endmodule

ref_code:
module sub_64bit(
  input [63:0] A,
  input [63:0] B,
  output reg [63:0] result,
  output reg overflow
);
  always @(*) begin
    result = A - B;

    // Overflow happens when the sign of A and B are different, but the sign of result matches B
    if ((A[63] != B[63]) && (result[63] != A[63])) begin
      overflow = 1;
    end else begin
      overflow = 0;
    end
  end

endmodule
